setfenv(1, VoiceOver)

if GetLocale() ~= "ptBR" then
    return
end

GossipText = {
    GossipLookupByNPCID = {
        [68] = {
            ["$GOutro empreendedor:Outra empreendedora;, hein? Bem, você pode encontrar a Casa de Leilões no Distrito Comercial. Fica perto do banco."] = "3b18fc0710278c6aa12fb30a85999aaf",
            ["$GUm caçador:Uma caçadora;, é? Bem, então você precisa conversar com Thorfin Escudopétreo no Distrito dos Anões.   Ah, e diga a ele que, se eu pisar em algum presentinho do bicharoco dele mais uma vez, o único lugar em que ele vai treinar caçadores é atrás das grades do Cárcere!"] = "d9d6fc265ce7e558402d3ca53747dac5",
            ["$GUm filho:Uma filha; da natureza, é? Basta procurar perto do poço lunar no Parque."] = "a63f0a77a472eab18caf48ea8320d27e",
            ["A Catedral da Luz na Praça da Catedral é o lar dos sacerdotes de Ventobravo. Lá, você vai encontrar a alta-sacerdotisa Laurena."] = "bb897a746e8a30c2b211e9076b6a286d",
            ["A Catedral da Luz é o centro das práticas de cura de Ventobravo. Lá, você encontrará Suzi Lira, que poderá ajudá-$Glo:la; a aprender o ofício."] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
            ["A Contadoria de Ventobravo fica perto dos portões frontais do Distrito Comercial. Quando você se cansar de contar seu dinheiro, não deixe de dar uma passada na Rosa Dourada para beber alguma coisa."] = "554b8726d09d342022c5c7eaf5a9818e",
            ["A Duncan Tecidos tem em seu quadro um dos melhores alfaiates de Ventobravo: Georgio Bolero. Procure a loja no Distrito dos Magos."] = "8706ad14fe81bd7bfe9d6986ff68ed63",
            ["Ah, a Rosa Dourada... com seus colchões macios e banhos quentes... só de pensar naquela estalagem me dá vontade de bocejar... *uuáááhhh*... Sorte sua estar indo pra lá... ela fica no lado oeste do Distrito Comercial... travesseiros macios, cobertor quentinho. *uuáááhhh*"] = "e84a11ab6b3896ecf97c8adfbc08636c",
            ["Ah, você está procurando Lucas Cordel. Ele tem uma loja no lado de fora do Distrito da Magia, no caminho para o Cárcere."] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
            ["Ah, você está procurando iluminação arcana? Não tem lugar melhor do que o Sacrário dos Teurgos no Distrito dos Magos."] = "0493aff58b480f500d524b265550d281",
            ["Ahhh, o que você procura é o Centro de Visitantes de Ventobravo. Fica no primeiro prédio à esquerda passando pelos portões principais, vindo do Vale dos Heróis."] = "646cbbc2bf91bdaa020beb25f4e0a678",
            ["Ahhh, você está procurando Dungar Tragolongo. Ele tem alguns dos grifos mais rápidos deste lado de Khaz Modan! Você vai encontrá-lo nas muralhas, no Distrito Comercial."] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
            ["Altamiro Beltron está no Centro de Visitantes de Ventobravo, que fica no Distrito Comercial."] = "53cfbdba892d116c2e03388c9fd6d5d0",
            ["Aquele vagabundo do Gurjão... Passa o dia todo sentado pescando na doca em frente ao Distrito Comercial. Tenho certeza de que ele é bom nisso, já que gasta tanto tempo praticando. Se você quiser aprender, por que não vai lá falar com ele?"] = "2472ef40c4054390e47d26a2790dcef8",
            ["As Sentinelas da Asa de Prata precisam do máximo de ajuda que conseguirem na luta contra os Pioneiros do Brado Guerreiro, $n. Caso queira lutar, vá à Bastilha Ventobravo e fale com Elfarran."] = "a28ad28e180fb23f6b2f30a8926dd8d3",
            ["Bah, esses ladinos só fazem dificultar o nosso trabalho aqui em Ventobravo. Eu queria poder arrastar o Osborne e o Mathias da Cidade Velha direto para o Cárcere."] = "6e24adae0babfe7f1e128960d09c55af",
            ["Bem, você vai encontrar Theridan ou Maldryn perto do poço lunar no Parque. Vá para o oeste de Ventobravo, fica ao norte do Distrito dos Magos, mas a oeste da Praça da Catedral."] = "2c1e9110dff51f5d1d491b13523c5989",
            ["Bruxos, hein? Bom, não foi de mim que você ouviu isso, mas dizem por aí que eles costumam se reunir em um bar chamado Cordeiro Imolado no Distrito dos Magos."] = "f05de425d7bd02752037b8477cf01b53",
            ["Dê uma olhada lá para a Cidade Velha, no Quartel ou na Taberna do Javatusco Saltitante. Se você for à taberna, não deixe de experimentar as deliciosas cervejas. Elas botam as cervejas enânicas no chinelo."] = "c621f0b9a4a6a6290dd5972a302122fc",
            ["E para onde você gostaria de ir?"] = "2402ec9453525b4ec16e1180457c7cfb",
            ["Ei, isso me faz lembrar que tenho que mandar minhas botas-foguete para o conserto. Um conselho para a vida, $gamigo:amiga;: botas-foguete e grifos não se bicam.   Ah, mas você não sabe o caminho... É só você ir até o Distrito dos Anões para encontrar Lilo Chispafuso ao fundo."] = "bb3fee63f3293484e591674a691d3c88",
            ["Ela fica no Distrito Comercial, cidad$Gão:ã;. Da entrada de Ventobravo, é praticamente uma linha reta."] = "568c01f3e19d99d5f41ea3aac2056ebe",
            ["Em qual campo de batalha você está $ginteressado:interessada;?"] = "481f209702cc74fc87fe4569d25b276b",
            ["Então é com Thelman Petrapunho que você tem que falar. Ele fica na Bastilha Ventobravo, na presença do Rei."] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
            ["Escondida no Distrito dos Magos, fica uma lojinha chamada O Alquimista. Você verá várias lojas estranhas pelo caminho do Distrito dos Magos, mas se você se dirigir ao perímetro externo, vai encontrá-la."] = "8651024fca6f7bd42a0336d52e7d69fc",
            ["Grifos, é? Nunca dei muita bola para essas feras, mas cada um na sua.  Dungar Tragolongo está na muralha do Distrito Comercial."] = "258744fe85450f544093d5fd17856341",
            ["Há vários estabelecimentos comerciais em Ventobravo onde se pode beber, mas só um deles deixa você passar a noite lá. Vá para a Rosa Dourada no Distrito Comercial. Ouvi dizer que eles têm preços acessíveis e lençóis limpos."] = "44af32f368e03c09b89fe9f87be3875e",
            ["Jenova Escudopétreo, do Distrito dos Anões, é quem você está procurando. Ela cuida das feras dos caçadores enquanto eles procuram treinamento com o pai dela."] = "9654c77653b91d446f531295982fbec7",
            ["Laurena é a alta-sacerdotisa de Ventobravo. Você vai encontrá-la na Catedral da Luz, que fica na Praça da Catedral."] = "4a22a1b67aa8fe418d517ebb0e371796",
            ["Lucas Cordel tem uma lojinha no canal, próximo ao Cárcere. Tenho certeza de que ele vai poder lhe ensinar a arte do encantamento."] = "91e3f367dbb0e83b362a5880d1271dc4",
            ["Minha sugestão é procurar na Catedral da Luz, na Praça da Catedral."] = "7c15eb60533829779dc9fd0c60d26a6a",
            ["Nada como passar o dia pescando no Lago de Cristal. Foi Arnoldo Gurjão que me ensinou. Ele geralmente está nas docas no Distrito do Canal, pescando o dia todo.   Ah, não acredite em nenhuma história que ele contar sobre monstros nos canais."] = "852f678dbc06d3601bdf168e7032735a",
            ["Não há jeito melhor de se aprender Primeiros Socorros do que sob a supervisão de Suzi Lira na Catedral da Luz.   Para chegar lá, basta procurar os telhados amarelos ou as torres da Catedral, que podem ser vistas de praticamente qualquer lugar da cidade."] = "b1be3018807cc2da500145c8c2b10794",
            ["Não há nada melhor do que estar em comunhão com a natureza... pelo menos é isso que os elfos noturnos me dizem. Não sou muito de conversar com flores e árvores, mas tenho certeza de que Tannysa pode ajudá-$glo:la;. Ela fica no Distrito dos Magos, do lado de fora da loja O Alquimista."] = "42747362bb8e6d2164d7e79747248058",
            ["Não sei como eles fazem... Aquelas caixas de correio devem ser portais mágicos ou coisa assim. Porque, o dia todo, eu vejo gente em volta da caixa de correio ao lado do banco tirando espadas, escudos e armaduras daquela caixinha!"] = "b4b551dc6175faa3e32ad05a88b10b09",
            ["O Banco de Ventobravo fica no Distrito Comercial, logo a noroeste dos portões da cidade. Deixe-me marcar no seu mapa."] = "8fedf8298f3edb222d5b5f4355c58675",
            ["O Castelo Asa de Prata precisa mesmo da sua ajuda. Fale com Elfarran na câmara de audiências na Bastilha Ventobravo."] = "ab67b49961ce98725cccb8a6b0e8e7ef",
            ["O Mestre Woo Ping domina praticamente todas as armas conhecidas. Ele é especialmente perigoso quando usa espadas. Se você quiser treinar com ele, o mestre passa boa parte do tempo no Arsenal Viegas, aguardando novos carregamentos de armas."] = "ea46258d498568523f3fadf071cc9af0",
            ["O instrutor de engenharia residente em Ventobravo é um gnomo habilidoso que se chama Lilo Chispafuso. Você vai encontrá-lo nos fundos do Distrito dos Anões."] = "05e90b70ee82c6ab15e68fec597454c2",
            ["O quê? Não sei de nenhum instrutor de bruxos em Ventobravo.   Se bem que... Há relatórios de atividades demoníacas lá no Cordeiro Imolado, no Distrito dos Magos. Acho que você poderia dar uma olhada lá."] = "f6a52f523eecff532c9530eae7d0e89a",
            ["O vigor de Woo Ping é impressionante. Fico com pena do boneco de treinamento, depois de observar Woo Ping praticando técnicas de combate por horas. Não consigo imaginar pessoa melhor para treiná-$Glo:la; em combate armado."] = "312810e5deb14cd60aa19428f7f51227",
            ["Olha só quem está subindo na vida! O lugar que você está procurando é o Salão dos Campeões. Ele fica no canto sudeste da Cidade Velha. Se você já for oficial, pode entrar no salão. Se não for, ainda dá para falar com a Oficial Areyn. Boa sorte!"] = "a0e2103ae01da9c6c1707056a504c6ae",
            ["Os magos se reúnem no Sacrário dos Teurgos no Distrito dos Magos. Eles têm uma torre e tanto por lá. Deixa o nosso quartel com cara de choupana de camponês."] = "338c8fab07f57033e48217d5973c15df",
            ["Parece que você quer falar com o Maginor Dumas! Ele geralmente está no Sacrário dos Teurgos no Distrito dos Magos. Mas, é claro, que nunca se sabe quando e para onde aqueles magos vão se teleportar."] = "fa0d9c855011039c74c70b23db0b82ea",
            ["Procurando treinamento, é? Eu poderia treinar você melhor do que qualquer um em Ventobravo, mas a guarda proíbe. Você vai ter de se contentar com um daqueles coroas que ficam lá pelo Quartel ou na Taberna do Javatusco Saltitante, na Cidade Velha."] = "cd7fa3fdce25e94d80b36771810f1e93",
            ["Quer aprender couraria, é? Simão Correia pode ensinar a você. Ele está na Cidade Velha, no Pelego Protetor."] = "52ef93000b10574ffb40f6f451597e26",
            ["Quer dizer que você não está sentindo o cheiro das forjas enânicas daqui? Bem, se você quer estudar ferraria, terá que procurar Therum Baixaforja. Ele está no Distrito dos Anões, que fica logo ao norte da Praça da Catedral."] = "a3a18a74f32a8ebab3109103db8d0fd5",
            ["Quer dizer que você não tem estômago para cavalgar um grifo, né? Bem, sorte a sua que temos uma alternativa para manter seus pés no chão... ou quase. É o transportador gnômico de pessoas, o Metrô Correfundo, convenientemente localizado atrás do Distrito dos Anões."] = "b8a17986e4d6330f2e74f8f8a53c0d86",
            ["Quer dizer que, de repente, você virou $Gum 'defensor:uma 'defensora; da Aliança'!? Imagino que queira ir ao Salão dos Campeões. É na Cidade Velha, mas não vão deixar você entrar a menos que você seja u$Gm:ma; oficial. Pode ser que você tenha que se resignar a falar com a Oficial Areyn. Agora circulando. Vai."] = "33278f8101e800c93fc3d2385cfed699",
            ["Quer fazer uma viagem de grifo, é? Dungar guarda os bichos no parapeito da muralha do Distrito Comercial. Não se esqueça: Segure firme!"] = "7df84a254c23565acaa7fc468ead3ab2",
            ["Queria poder te acompanhar, $n. Vá à Bastilha Ventobravo. Thelman Petrapunho fica na câmara de audiência do Rei. Ele vai te ajudar a chegar no Vale Alterac."] = "5da822272073a4d726872184c3421ca6",
            ["Sabe, eu poderia perfurar um orc ou fatiar um troll. Poderia até marcar a ferro em brasa minhas iniciais no flanco de um ogro, mas eu simplesmente não consigo esfolar um animal. Vai entender, né?   Bem, se você tiver estômago para isso, então vá falar com Maris Granger na loja Pelego Protetor, que fica na Cidade Velha."] = "c7ce82c152a63bc669f1d309ce17f9bd",
            ["Se está procurando instrutores de druidas, vá até o Parque. Theridan e Maldryn geralmente estão perto do poço lunar no centro do distrito."] = "6ca4fdf838b083f58d40a21536adeaed",
            ["Se está procurando os ladinos, vá à Cidade Velha. Fica na parte nordeste de Ventobravo."] = "cd52082b0fdc76c7dded230c974a2ebf",
            ["Se precisar abrigar suas feras enquanto treina outra, fale com Jenova Escudopétreo no Distrito dos Anões."] = "b68ea919378ae726f910e862a386d16f",
            ["Se você precisa de treinamento em alquimia, só há um lugar em Ventobravo: O Alquimista. Fica no Distrito dos Magos, no lado voltador para os canais."] = "7034523efe4bfc8203b790a1d127dca2",
            ["Se você quer aprender esfolamento, é melhor passar no Pelego Protetor, que fica na Cidade Velha."] = "6f55eb7e6eebe144bc957790dae41464",
            ["Se você quer se tornar $Gum poderoso paladino:uma poderosa paladina;, não existe melhor instrutor do que o lorde Grayson Quebrassombra. Ele pode ser encontrado na Catedral da Luz."] = "2d22a7afddcc8d88b9c1353ae28daf09",
            ["Se você quer se tornar $gum:uma; grande $gcozinheiro:cozinheira;, vá até a Taberna do Javatusco Saltitante, na Cidade Velha, e fale com Stephen Ryback. Aquele homem sabe assar uma costela como ninguém.  Rapaz... agora me bateu uma vontade de comer aquelas famosas costelas. Mas não espere que ele ensine essa receita!"] = "dbe19e29f297c8e1fb35a95e50f89466",
            ["Seu negócio é couro, é? Acho que você deveria falar com Simão Correia lá na Cidade Velha. Ele tem uma loja chamada Pelego Protetor."] = "02b8fd48e20c73453938adc9f4995c2c",
            ["Tem um grande cozinheiro na Taberna do Javatusco Saltitante, na Cidade Velha. Eu já o vi usando uma faca e, cá entre nós, acho que ele nem sempre foi um cozinheiro. Não me entenda mal... se você ainda quiser aprender, ele é o melhor que temos."] = "af66b0b5d2d42f34571240ac0c887807",
            ["Tem uma caixa de correio convenientemente localizada entre o Banco de Ventobravo e a Rosa Dourada no Distrito Comercial."] = "bb63ff9d75c7726f1d06e21fe2021b8b",
            ["Therum Baixaforja é o anão com quem você quer falar. Na minha opinião, ele é um dos melhores ferreiros daqui. Ele está no centro do Distrito dos Anões."] = "a4956fb4f50c46eaea4f68dd50ceb194",
            ["Thorfin Escudopétreo veio lá de Altaforja para nos trazer sua perícia como caçador. Se você não se importar de respirar o ar fumacento do Distrito dos Anões, vai encontrá-lo na casa dele na área nordeste do distrito."] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
            ["Um alfaiate? Bem, se você ficar tempo suficiente por aqui, vai acabar ouvindo falar no Georgio Bolero. Já faz alguns meses que ele dita as tendências da moda. Se você deseja aprender com ele, vai encontrá-lo no Distrito dos Magos, no perímetro externo."] = "9cba4dc5407b5b21f860b325ab149a86",
            ["Vai formar uma guilda, é? Então, boa sorte!  Fale com Altamiro Beltron no Centro de Visitantes de Ventobravo. Fica no Distrito Comercial, logo após a entrada pelo Vale dos Heróis."] = "dbd178f951b41e05c59af921ec3b7725",
            ["Você devia falar com Gelman Manopedra. Acho que ele tem uma casa no Distrito dos Anões, mas não me lembro bem. Eu daria uma olhada lá."] = "8f8f48c440d58b1a783b868dd9222e74",
            ["Você encontrará a dama Hoteshem na câmara de audiência do rei. Ela $Go:a; ajudará a chegar à Bacia Arathi, onde a Liga de Arathor precisa de auxílio contra os Profanadores."] = "9ff1ef7f7918452a7571c3f770ab4e14",
            ["Você está procurando instrutores para qual profissão?"] = "ce83ae92effc9c6509cef60c5f919389",
            ["Você está procurando qual instrutor de classe?"] = "7e357056bac5b73342ac2bee0458e300",
            ["Você já ouviu falar do metrô, não ouviu? É um passeio e tanto! Fica no Distrito dos Anões, lá no fundo. Ah, e não fique com as pernas e braços para fora do vagão enquanto o trem estiver em movimento."] = "98484e0cd95c72af21e16247f3eead70",
            ["Você pode encontrar os guerreiros na Taberna do Javatusco Saltitante ou no Quartel. Os dois ficam na Cidade Velha. Mas acho melhor procurar na taberna."] = "9434f3b21efa2de084243d600d530ff5",
            ["Você precisa é falar com Osborne. É o melhor professor da arte da furtividade que temos em Ventobravo. Procure-o na Cidade Velha."] = "5079ccedcf83df1e6554116dbaa337bd",
            ["Você vai encontrar Tannysa do lado de fora da loja O Alquimista, no Distrito dos Magos."] = "356b1700581f2c27333ab266a26bb077",
            ["Você vai encontrar o mestre de grifos na muralha nordeste, que tem vista para o Vale dos Heróis."] = "f5c1db946eb2f4fba13e922275d9fb95",
            ["É admirável o que a Liga de Arathor está tentando fazer na Bacia Arathi. Pena que aquelas abominações mortas-vivas e seus amigos da Horda estejam atrapalhando.  Vá até a Bastilha Ventobravo.  Lady Hoteshem $go:a; aguarda na câmara de audiência do rei. Ela $Go:a; ajudará a ir para a Bacia Arathi."] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
            ["É bem coisa de anão, enviar um especialista em minas de Altaforja para nos ensinar a minerar. Será que é tão difícil pegar uma picareta e lascar algumas rochas? Bem, já que ele está aqui, você deveria vê-lo de qualquer maneira. O nome dele é Gelman e ele mora no Distrito dos Anões."] = "64070f95813e914bdca6f15e390c919e",
        },
        [197] = {
            ["Olá, $Gcidadão:cidadã;! Você me parece bem forte. Temos guardas de menos e trabalho demais, e você pode me ser útil..."] = "2343fa9b01b2ca00b5bc7a390ac07935",
        },
        [198] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["Saudações, $Gmago:maga;. $gInteressado:Interessada; em adquirir uma maior compreensão do mundo da magia?"] = "3ddc082eac22c52bb34743331a694904",
            ["É um prazer vê-$glo:la;, $c. Meu conselho a você é o seguinte: ao viajar pelo mundo, cuidado com a magia, pois ela prejudica os inexperientes."] = "54074b0b08d3a499512ae6fba95f3115",
        },
        [223] = {
            ["Quando saí do túmulo, com muito esforço, achei que minha família me acolheria de braços abertos. Ao invés disso, eles me enxotaram do vilarejo, gritando numa língua que eu não compreendia mais."] = "94095eb43627763b471b3b24bdf02a82",
        },
        [233] = {
            ["Tempos difíceis, né, $n? Onde que que você vá tem alguém precisando de ajuda, e minha esposa e eu não somos exceção."] = "d9ee732b87b8a6f2898035304c1bf290",
        },
        [277] = {
            ["Os melhores preços de Ventobravo, $Gamigo:amiga;. Não vai achar nada mais barato. Em que posso ajudar?"] = "0a50227fd4a79a221c5e74147031f06e",
            ["Você está só dando uma olhada ou está procurando alguma coisa específica?"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [295] = {
            ["$GBem-vindo:Bem-vinda; à minha estalagem, viajante $Gcansado:cansada;. O que posso fazer por você?"] = "e3e01e02de026cbe5e2560a468bbdebb",
            ["Ao dar provas de amor para os cidadãos, eles lhe darão, em troca, presentes diversos. Alguns você pode querer manter para si e usar, enquanto outros você pode juntar para dar ao seu herói favorito! Para entregá-los, fale com Ligeirinho Coração.$B$BO Ligeirinho fica perto de Bolvar, Magni ou Tyrande."] = "fa856e726cbf60331453148913410f70",
            ["Ao dar provas de amor para os cidadãos, eles lhe darão, em troca, presentes diversos. Alguns você pode querer manter para si e usar, enquanto outros você pode juntar para dar ao seu herói favorito! Para entregá-los, fale com Ligeirinho Coração.$B$BO Ligeirinho fica perto de Caerne, de Sylvana e de Thrall."] = "616aaf989a9683312fafbb75a48fe26b",
            ["Ao usar perfume ou colônia, você verá quem está amoroso. São essas pessoas que aceitarão as provas de amor e darão um presente em troca.$B$BMas lembre-se: para dar uma prova de amor a alguém, você precisa da fragrância correta! Homens gostam do aroma do perfume, e mulheres preferem o da colônia."] = "206f059d0c629c5d37a5efc62769a4a3",
            ["Não, eu não, mas tem muita gente procurando amor por aí. Você devia comprar as minhas provas de amor, passar uma colônia ou um perfume e, depois, disseminar o amor!"] = "137f53b5268a04b1b5bdb21820557b14",
            ["O que dá para fazer em uma estalagem?$B$BBom, quando você se hospeda numa estalagem, o descanso é muito mais confortável. Portanto, você fica '$Gdescansado:descansada;' muito mais rápido do que ficaria na floresta. Heróis descansados ganham experiência mais rápido.$B$BFale com qualquer estalajadeiro e receba uma Pedra de Regresso, que levará você de volta àquela estalagem rapidamente."] = "8fc274a3d994a2459bdce3fd3dc98705",
            ["Provas de amor são recadinhos afetuosos que você manda para os amorosos habitantes de cidades e aldeias. As pessoas vão retribuir com um presente de afeto.$B$BOu, se você já for $go adorado:a adorada; de alguém, as pessoas lhe darão, pelo menos, um presente de amizade."] = "d268a407b36e89a7c70ab981fb46abd7",
        },
        [328] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["Saudações, $Gmago:maga;. $gInteressado:Interessada; em adquirir uma maior compreensão do mundo da magia?"] = "3ddc082eac22c52bb34743331a694904",
            ["É um prazer vê-$glo:la;, $c. Meu conselho a você é o seguinte: ao viajar pelo mundo, cuidado com a magia, pois ela prejudica os inexperientes."] = "54074b0b08d3a499512ae6fba95f3115",
        },
        [331] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["Saudações, $Gmago:maga;. $gInteressado:Interessada; em adquirir uma maior compreensão do mundo da magia?"] = "3ddc082eac22c52bb34743331a694904",
            ["É um prazer vê-$glo:la;, $c. Meu conselho a você é o seguinte: ao viajar pelo mundo, cuidado com a magia, pois ela prejudica os inexperientes."] = "54074b0b08d3a499512ae6fba95f3115",
        },
        [332] = {
            ["$GBem-vindo:Bem-vinda; ao quartel-general da AVIN, $n."] = "f02518f56be86de855c4a5c585841f34",
        },
        [347] = {
            ["A Guarda de Lançatroz será destruída! Você está $gpreparado:preparada; para o Vale Alterac, $c?"] = "81ed3ff7e3aa4663fea43677ac077dd8",
            ["Sinto muito, $c, mas será impossível sobreviver ao Vale Alterac com a sua experiência."] = "b83ab9c1a9dd85b93121a8a221e21094",
        },
        [352] = {
            ["As grandes feras conhecem caminhos impossíveis de se encontrar a pé. Elas podem te levar depressa e talvez te mostrar algo novo ao mesmo tempo."] = "483ae8ef81d9a1fa5470403f505b2d87",
            ["Para onde você quer ir, $grapaz:moça;? Por apenas algumas moedas, os meus grifos levam você mais depressa do que o cavalo mais veloz."] = "6b05ee484d45803ee175e05a07d644f4",
        },
        [375] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "768f0928588ebe52253715a9f6b21ad7",
            ["Não vire as costas para a Luz, $c, ela pode salvar sua vida algum dia."] = "120875f188ac12780f811009b51a783b",
            ["Tenho fé de que a Luz está com você, $n. Tem alguma coisa em que posso ajudar?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
        },
        [376] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "768f0928588ebe52253715a9f6b21ad7",
            ["Não vire as costas para a Luz, $c, ela pode salvar sua vida algum dia."] = "120875f188ac12780f811009b51a783b",
            ["Tenho fé de que a Luz está com você, $n. Tem alguma coisa em que posso ajudar?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
        },
        [377] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "768f0928588ebe52253715a9f6b21ad7",
            ["Não vire as costas para a Luz, $c, ela pode salvar sua vida algum dia."] = "120875f188ac12780f811009b51a783b",
            ["Tenho fé de que a Luz está com você, $n. Tem alguma coisa em que posso ajudar?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
        },
        [384] = {
            ["Após anos usando as melhores técnicas de criação e empregando todos os cuidados possíveis, tenho o privilégio de lhe mostrar estes cavalos! Por favor, olhe o quanto quiser enquanto escolhe! Um cavalo é uma companhia para a vida toda, $Gamigo:amiga;. Não se deprecie – compre seu corcel aqui hoje!"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
            ["Perdão, mas não estou disposto a vender cavalos a nenhum indivíduo que não seja considerado no mínimo exaltado pelo Reino de Ventobravo. Estes corcéis são os melhores do mundo, e não os queremos nas mão de nossos inimigos.$B$BNão estou falando que você é $Ginimigo:inimiga;, é claro... conquiste a confiança de Ventobravo para podermos fazer negócios."] = "33c0e9087e12555f8dc52cc2a68cccb1",
        },
        [459] = {
            ["As trevas não aceitam você, $c. Acabe com essa ladainha e saia da minha frente! Vá!"] = "2aabd37566ced1f9550e86910bb3baf8",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "768f0928588ebe52253715a9f6b21ad7",
            ["O conhecimento arcano corrompe apenas os fracos. Mesmo se você não seguir o caminho do bruxo, será bom lembrar-se disso."] = "bf6b174b1213cc9fc8478d3b5f2b4971",
        },
        [460] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
            ["Infelizmente, seu quociente de trevas não é alto o bastante para eu me dar ao trabalho de conversar com você. Com licença."] = "8045db4a1a25656b86eb87b955fbe642",
            ["O arcano só corrompe os fracos. Continue treinando, ou poderá ter um destino semelhante."] = "073492d1b775dad17b73e4495accc8b7",
        },
        [461] = {
            ["As trevas não aceitam você, $c. Acabe com essa ladainha e saia da minha frente! Vá!"] = "2aabd37566ced1f9550e86910bb3baf8",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "768f0928588ebe52253715a9f6b21ad7",
            ["O arcano só corrompe aqueles que são fracos. Mantenha-se firme em seu treinamento ou você encontrará destino igual."] = "c381816693d5bcf8cf6644c3ad7a0dea",
        },
        [483] = {
            ["Os melhores preços de Ventobravo, $Gamigo:amiga;. Não vai achar nada mais barato. Em que posso ajudar?"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["Você está só dando uma olhada ou está procurando alguma coisa específica?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
        },
        [491] = {
            ["Eu tento manter o Morro da Sentinela abastecido, o que não é nada fácil com tanta ação."] = "f25d9eb86b1a32dfb1649beab901ef4c",
        },
        [514] = {
            ["Sinto muito, estou muito ocupado no momento fazendo ferraduras para Vervo Obom de Vila Plácida."] = "80c8a703f2783e988393cdc3f26954dd",
        },
        [523] = {
            ["Para onde você está indo? Bem, se quer chegar lá rápido, então não fique só querendo!"] = "a8c3fee28c1869e9b77707e11b8cd0a2",
        },
        [543] = {
            ["Sinto muito, $gmeu amigo:minha amiga;. Eu só ajudo caçadores e as feras deles."] = "4c9a93178a8bd81be46f856336284914",
            ["Você veio adquirir treinamento para as suas feras?"] = "89218c24a0eff1fa5c10022467769ef7",
        },
        [658] = {
            ["Mas olha se tu não é mais parrud$Go:a; que carneiro na engorda! Talvez tu possa me ajudar com uma coisa ou outra. Capaz que essa aprendizada cheirando a leite vai dar conta... Não tem mais ninguém por aqui, e eles têm muito mais o que fazer."] = "5fc097432cec6da6622815d859a41a7a",
        },
        [716] = {
            ["O mestre Rosarães tem uma grande caçada pela frente. É muito mais relaxante ajudá-lo a se preparar para um dia na selva do que ajudá-lo a se preparar para combate. Se bem que eu sinto saudades daqueles gloriosos momentos no campo de batalha."] = "e3a348a35882a9d1e3d9c86ff56b6bbe",
        },
        [727] = {
            ["A Caixa-forte é o banco mais perto que tu vai encontrar por essas bandas."] = "83965dbeffe98cceda0d3e3dbf0734c2",
            ["Aaah, uma estalagem, né? Bom, tu não vai achar lugar melhor do que a Destilaria Cervaforte. Descansa se precisar, mas não deixa de tomar umas cervejinhas enquanto estiver lá."] = "e66a69d239e7c3f1206d7f638c44bec1",
            ["Ah, $gum sacerdote:uma sacerdotisa;, né? O bom e velho Maxan sempre pode ser encontrado tomando um goró na Destilaria Cervaforte, caso você precise de um pouco de treinamento."] = "9a7b6a50e57d38d1acb4f3bff531e0f2",
            ["Ah, Pedracenho quase não sai de Altaforja ultimamente. Por isso, se tu pretende aprender a profissão de alfaiate, vai ter que ir até ele."] = "63ec46e6d95ea9bc754d4ccb65dd8202",
            ["Altaforja é o melhor lugar pra encontrar coureiros. Se bem me lembro, tem uma oficina perto da Grande Forja que deve ter o que tu precisa."] = "712130efaf95afb9ccb5f2a5c069c0fc",
            ["Aquele Granis Celeraxa consegue beber mais que um motor de seis canecos e ainda dar um golpe preciso com o machado. Mas, se tu tiver atrás de treinamento, é melhor pegá-lo enquanto ainda dá pra entender o que ele fala."] = "ee5ecc14e2bf49a6990e74cae4288e7b",
            ["Arre! Agora, sim, estamos conversando! Aposto que Granis Celeraxa pode te ensinar umas coisinhas sobre brandir uma lâmina. Ele deve estar lá na Destilaria Cervaforte agora."] = "0fd2049ea24b3dbd43761a96e891bd61",
            ["Arre... $gum paladino:uma paladina;? Bom, $gguri:guria;, tu tá com sorte! Avar Marroforte acabou de voltar do treinamento e, agora, tá instalado lá na Destilaria Cervaforte em Kharanos."] = "9d8f2dd4c4db277f02b3c5d5f15c9354",
            ["Bah! Isso, sim, é uma habilidade que vale a pena aprender. Tognus marreta a bigorna com uma fúria que não se vê sempre. Vai lá dar uma palavrinha com ele e vê o que ele pode te ensinar."] = "5240f70aad5a8e58147ce8fae9c1ec57",
            ["Bem, $Grapaz:moça;, Shelby Pedrerneira fica em frente à Destilaria Cervaforte em Kharanos. Ela vai cuidar bem de qualquer fera que você tiver."] = "bee5611eb524aaf54dfb7c803d87d4c9",
            ["Bom, tu não vai ter muita sorte tentando achar um alfaiate aqui. Altaforja é o lar de vários talentos do ramo. Por que tu não vai até lá e se informa com algum guarda?"] = "720fafcfb6472426d4149a74769fda89",
            ["Bruxos... Não dou muita bola pra essa laia. Que nem aquele Grimrizz que montou uma loja perto da Destilaria Cervaforte. Provavelmente, a cerveja vai chocar por causa dele. Bruxos... bah!"] = "60bf6744b34a4b35ea7e3f938b4de2fd",
            ["Com certeza tu vai ouvir Tognus marretando a bigorna quando tu estiver em Kharanos. Mas, caso tu não tenha tirado a cera do ouvido recentemente, é melhor dar uma olhada lá na ferraria."] = "9f64ea1b3225a2261a71922332f8c889",
            ["Com certeza, tu vai encontrar Maxan Begurno entornando umas na Destilaria Cervaforte. Dá um pulo lá pra tomar umas cervas e ver se ele pode te ensinar alguma coisa nova."] = "f9ef4e04eea4de713fc61313fd8a4c8e",
            ["Esse tipo de magia... coisa boa não é. Sei lá porque deixaram aquele Grimrizz se estabelecer logo ao lado da Destilaria Cervaforte, com tanto lugar por aí! Vê se fica longe dele, hein?"] = "f1180972db6665288081c1cfc7b5f408",
            ["Eu soube que tem uma loja em Altaforja administrada por gnomos que é especializada em alquimia. Você deveria dar uma olhada lá."] = "e59e7a5d5007c14bc99785f8ce315a5c",
            ["Gremlock nem sempre tem muita sorte quando cozinha, mas ele tem umas receitas deliciosas. Vá falar com ele na Destilaria Cervaforte e vê o que ele pode te ensinar."] = "812ca9ddb549b5088d51719a6d51434b",
            ["Nem. Não tem nenhum alquimista aqui em Dun Morogh. É melhor tu dar uma olhada lá em Altaforja... tenta com os gnomos no Beco da Gambiarra."] = "f7cf19aeccddff42a9a0b22c505718cc",
            ["Não tem muita coisa pra se pescar por aqui, mas o pouco que tem, com certeza, o Paxton fisga. Tu vai encontrar ele pescando no Lago Nevado."] = "467b47eb9a3d4006f250fad9ecb18eb0",
            ["Não tem muitos lugares onde dá pra pescar por aqui. Paxton conhece todos e, provavelmente, não vai te contar de alguns deles. Por que tu não vai até o Lago Nevado e vê o que ele te conta?"] = "8bbfc8f6de8eca0089d8559839569436",
            ["Não. Não tem ninguém aqui que possa te ensinar herborismo. Mas, acho que tu vai ter mais sorte lá em Altaforja."] = "5aaf2f083eef745315ab1a2dc692fcb0",
            ["O Bronk passar o dia inteiro apertando parafusos, mas acho que ele anda com alguns parafusos soltos na cabeça, se é que você me entende. Mesmo assim, ele ainda sabe construir tudo que é tipo de mecanismo. Tu devia dar um pulo lá na Garagem do Gradaço pra falar com ele."] = "d505dd7c90c149052d96dc5021198f21",
            ["O banco mais perto que tu vai encontrar é a Caixa-forte em Altaforja, $gguri:guria;."] = "501c83ee292da27782fae1e60bf7c3f3",
            ["O bom e velho Thamner fez uns curativos em mim no outro dia, depois que briguei com um trogg nojento. Tenho certeza que o Thamner adoraria te ensinar a fazer um bom curativo."] = "93839b8ccc68c7af9e06e65b17c1fd90",
            ["O mestre de grifos mais próximo fica em Altaforja, perto da própria Grande Forja. Tu vai precisar ir até lá se quiser viajar de grifo."] = "c32efb4b50768d9afd75e50dc0393a88",
            ["Os Cervaforte têm uma estalagem em Kharanos que leva o nome deles. Dá um pulo lá pra tomar uma cerveja e descansar."] = "0ee12bb81d2947b566609b7ba822b401",
            ["Os esfoladores geralmente levam todas as peles pra secar em Altaforja. Por que tu não dá um pulo lá pra ver se algum deles te treina?"] = "12bf423a5f31db52e9d292ceb06ece6b",
            ["Pois é, parece que nós dois estamos procurando por Hogral Bakkan. De fato, ele é um anão e por isso, cedo ou tarde, vai se encaminhar pra Destilaria Cervaforte pra dar uns goles. Ele pode até estar lá agora."] = "1f4384179f7f2eff7cf1e505f549b91e",
            ["Primeiros Socorros podem não ser comparáveis à cura de um sacerdote, mas são muito úteis na hora do aperto. Recomendo que tu vá falar com Thamner na Destilaria Cervaforte para aprender o que puder."] = "a88b941bc8e164b364a0b5d642a579b5",
            ["Que eu saiba, não tem muitos encantadores aqui em Dun Morogh. Tu vai ter que visitar Altaforja se quiser aprender essa profissão."] = "ccffed48b48def2c22f1c44f31434020",
            ["Que informação tu precisa?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["Se quer saber minha opinião, eu acho que Grif passa tempo demais com os animais. Mesmo assim, ninguém conhece a tradição dos caçadores como ele. Procure-o perto da ferraria em Kharanos."] = "5d54f11c82628de5397e4af70d935d39",
            ["Se quiser aprender couraria, tu vai ter que viajar pra Altaforja. Ouvi dizer que tem uma loja das boas perto da Grande Forja, onde tu pode aprender o ofício."] = "5ca39ccf61fd158a1d527dc435d98222",
            ["Se quiser pôr as mãos em alguns documentos de criação de guilda, tu vai ter que pegar o rumo pra Altaforja e passar no Centro de Visitantes de lá."] = "395a422b3eb1d579d18416f0b5ef4bff",
            ["Shelby Pederneira abriga uma boa quantidade de feras dos caçadores locais. Ela fica ali pela Destilaria Cervaforte, caso você precise abrigar uma fera."] = "5011b7376cf9fbdf9a91842132fba2e6",
            ["Só tem um caçador por aqui que eu te recomendo visitar, e esse é Grif Selvacuore. Tu vai achar ele logo ao lado da ferraria em Kharanos."] = "3043df25383951a157419bf109bd7229",
            ["Tem certeza que tu não quer ser $gum guerreiro:uma guerreira;? Bom, é o teu que tá na reta no campo de batalha. Se tu quiser mesmo aprender a 'chacoalhar a varinha', é melhor tu falar com Magis Fagulhamanto. Ele tá lá na Destilaria Cervaforte."] = "3361a9560236765dd4f9f954267bed44",
            ["Tem um mago na Destilaria Cervaforte que pode te ensinar alguns feitiços novos. Se não me engano, o nome dele é Magis Fagulhamanto."] = "cfa572bac748ea1fa7e7c25dc2a4ae04",
            ["Todos esses tipos oficiais moram em Altaforja. Tu vai ter que dar um pulo no Centro de Visitantes de lá se precisar de documentos pra criação de guildas."] = "f9fd222716447c9fab43d7fdd2bdcab4",
            ["Tu devia dar uma olhada em Altaforja se estiver $gdecidido:decidida; a aprender encantamento. Acho que vi uma loja perto do mestre de grifos na última vez que estive lá."] = "e56f9fe4500923af12e19f791a883d14",
            ["Tu devia dar uma olhada na Garagem do Gradaço pra ver se acha o Bronk. Quando ele não tá fuçando alguma máquina esquisita, geralmente fica batendo papo com os pilotos sobre os tanques a vapor deles."] = "f4fbd7429c935511c5657b11b95d1303",
            ["Tu não achou que ia encontrar uma cidade enânica sem um minerador residente, achou? Geralmente tu pode achar o Yarr na Garagem do Gradaço, logo na saída de Kharanos."] = "1c9825e778eedca69936cc9dcbf549ef",
            ["Tu não vai achar nenhum esfolador aqui em Dun Morogh, $gguri:guria;. A maioria deles tá em Altaforja, se tu quiser treinamento."] = "6a6954aa23ff423b51b954fe09b144a8",
            ["Tu não vai encontrar um mestre de grifos em qualquer lugar de Dun Morogh, $gguri:guria;. Tu vai ter que ir até Altaforja se tu quiser pegar um grifo pra algum lugar."] = "f3c8a5a8b088f61349bd467d2e1e02b1",
            ["Tu tá procurando instrutor de qual classe?"] = "dcadd0f33e63218ef70a191c145117f6",
            ["Tu tá procurando instrutor de qual profissão?"] = "cf38911600ac02c04cb72aafa6596e66",
            ["Tá precisando de treinamento? Bom, Avar Marroforte tá sempre disposto a mostrar uma coisinha ou outra pros paladinos mais novos. Dá um pulo lá na Destilaria Cervaforte pra falar com ele."] = "63af3d038f4096f6bba167a9b297ef08",
            ["Tá procurando o Hogral? Bom, você já viu na taberna? Arre! Se tu quer um ladino, e um ladino anão, então é melhor começar pela estalagem. Vai logo dar uma olhada lá."] = "d218e9d1194ff62a08601af71245f9b8",
            ["Um minerador? Não pergunte 'se tem', $gguri:guria;, a questão é 'onde tem'! É do Yarr que tu tá falando, e acho que tu pode encontrar ele escondido na Garagem do Gradaço."] = "4ef02a6cde5565b37e151274512c0641",
            ["Uma Cervaforte Escura e um pouco da culinária do Gremlock formam a refeição perfeita. Você devia aprender com ele se realmente quiser ser $gum cozinheiro:uma cozinheira;."] = "d280277830161709ce905baf4cb22615",
            ["É incrível ver as florzinhas persistindo no frio de Dun Morogh, mas tu não vai encontrar nenhum herborista por aqui. É melhor ir pra Altaforja pra conseguir alguma instrução nessa profissão."] = "3fd9a5ca3019eefa0d287e45aeacd7da",
        },
        [738] = {
            ["Este lugar é perigoso, $n. Tenha cuidado por aqui."] = "a765bd81d4444d7fa3d03cdef9f00bd6",
        },
        [836] = {
            ["Eu vendo os melhores trajes de tecido e couro deste lado do vale!"] = "0f7736dc9f16d7152dca3f99e5a42807",
        },
        [837] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "31ab172e1a375db1c9157d594eb608d9",
            ["Espero que a Luz esteja contigo, $n. Há algo que eu possa fazer por você?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
            ["Que a Luz $go:a; proteja, $c."] = "852369f0d2fbc11e555e75fe5a433853",
        },
        [857] = {
            ["A Bacia Arathi foi outrora o nosso lar, e será novamente com a sua ajuda! Você vai nos ajudar, $c?"] = "72c6e36686e172b92adf3e89a32b9bdf",
        },
        [895] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "31ab172e1a375db1c9157d594eb608d9",
