        [944] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
            ["Saudações. Sou um gnomo instrutor de magos, e você é $Gum mago:uma maga;."] = "89ebbfb158e8bcf8fa80f49f22684c37",
            ["É um prazer ver você, $c. Quer um conselho? Faça amizade com um mago! Nós temos uma ou duas cartas na manga, temos sim..."] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
        },
        [957] = {
            ["Você acha que tenho tempo para perder batendo boca?"] = "a14f5faf742204672310f8f5b8263cb5",
            ["Você não é ruim, mas posso mostrar alguns truques que podem lhe ser úteis."] = "bfdb790af74bc4bc8fd2975752784485",
            ["Vê-se que você entende muito mais de ferraria do que eu, não tenho dúvida. Mas negarei até a morte se você contar a alguém que eu disse isso. Você deveria falar com Therum Baixaforja. Se tem alguém que pode lhe ensinar mais, é ele."] = "09a9c4ad934397dc02876bda84bad0ff",
        },
        [963] = {
            ["Não acredito que os oficiais de Ventobravo tenham mandado nosso exército quase todo para o exterior, enquanto nossa cidade sofre tanta pressão!$B$BCom ladrões vindo de Cerro Oeste e gnolls invadindo pelo leste e pelo oeste, é de espantar que Ventobravo não esteja sitiada."] = "e03d3aaa8df7e98fcb210403aad69ebd",
        },
        [985] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "3a364a4573d4825a6795e3bb454069d4",
