        [1317] = {
            ["Se você for capaz, ficarei feliz em lhe mostrar o caminho."] = "442191b2cfb08109059d8086031cf4ea",
            ["Sua confiança tem fundamento, viajante. Agora sua verdadeira educação deve começar!"] = "c1383f7b48e9dcb2540129e0a8e3528b",
            ["Um profissional de verdade conhece seus limites e não me envergonho em admitir que suas habilidades superam as minhas. Quero que você visite Kitta Ventígnea na Torre de Azora. Ela é bastante renomada – e com razão."] = "26d3bfbb22d8a54e39ab79db7fab0284",
            ["Você não está $Gpreparado:preparada;. Fale com Betty Quinn, ela está lá perto da escada. Fale comigo quando você tiver alcançado mais iluminação."] = "a4f377c48a85cd98cb6b0a714f4f8dfb",
        },
        [1318] = {
