        [2226] = {
            ["Saudações. Nossos morcegos são bem treinados e alimentados. Você não achará outros mais velozes."] = "fa762cd2402b543f4083d66aa2a57e13",
        },
        [2238] = {
            ["Sai daqui, $c, senão vão te prender também."] = "77c86eaf2987bb99b8be605cc0566070",
        },
        [2239] = {
            ["Um dos humanos está com a chave desta geringonça infernal. Acho que o nome dele é Elton."] = "89766cf6963eb64a903985c79701ac18",
            ["Você zomba de mim enquanto estou incapaz de me defender, preso a esta bola de ferro?"] = "ed5b5a2b8d5bee46993333b4c3f3eafe",
        },
        [2299] = {
            ["Para onde deseja voar?"] = "646a52da6f00e2b6b680741da2aab13f",
        },
        [2302] = {
            ["Saudações, $c. Você está $gdisposto:disposta; a lutar ao lado das Sentinelas da Asa de Prata na Ravina Brado Guerreiro?"] = "5f903d5d4508abe7b82460c9b5fcf80e",
            ["Sinto muito, $c, mas você não tem experiência o bastante para adentrar a Ravina Brado Guerreiro."] = "db6d2a2e49b804a2cf643369c2d678f3",
        },
        [2326] = {
            ["Eu posso lhe ensinar as técnicas de Primeiros Socorros."] = "61338bf2449f9fe80a4879d402d94c72",
            ["O estimado Doutor Gregório Casagrande pode prosseguir com o seu treinamento. Ele fica em Theramore, cuidando dos feridos no quartel."] = "ac5120ee0f594edb256081dbc34f1a6f",
            ["Ouvi dizer que Deneb Walker tem um livro que com certeza vai te ajudar a aperfeiçoar sua técnica de Primeiros Socorros. Ele está escondido em Stromgarde."] = "73b3f07d486fb7ce23b8df9c95511471",
        },
        [2327] = {
            ["Ah, $Gum colega médico:uma colega médica;. Eu adoraria lhe ensinar algo que lhe fosse útil em suas viagens."] = "5871df482a5322411e3250bb05234252",
            ["O estimado Doutor Gregório Casagrande pode prosseguir com o seu treinamento. Ele fica em Theramore, cuidando dos feridos no quartel."] = "1d81b661f251fb69f984eaa16be96159",
