        [4146] = {
            ["$GBem-vindo:Bem-vinda; ao Círculo Cenariano, $c."] = "7b9df1f70b5451c09c6a5311f56bf07e",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["Não posso treinar $Gum:uma; $c como você."] = "9bd1614bca66fd26e163696ba1b6b6fc",
        },
        [4155] = {
            ["$gBem-vindo:Bem-vinda; ao Banco de Darnassus. Nossos produtos incluem contas bancárias e cofres para itens valiosos. Você já é nosso cliente, $gsenhor:senhora;?"] = "72fdda7ff30be23db5fd1e0d05a37089",
        },
        [4156] = {
            ["Eu posso te ensinar técnicas de pesca."] = "b4dab18389b060695ecdb043fb33d368",
            ["Você só será capaz de melhorar sua técnica se encontrar o Nat Pagle no Pântano Vadeoso."] = "49c592e9b3c5eeb0c33e65239b4c0b06",
            ["Você é bem mais $ghabilidoso:habilidosa; do que eu. Ouvi dizer que o Velho Heming tem cópias de 'O Bagre e Você' lá na Angra do Butim. Se você ler o livro, vai ficar melhor ainda."] = "e170ac547f813e355db1e3b75f753815",
        },
        [4159] = {
            ["Há fundamentos que precisam ser dominados. Trianna está aqui por perto, fale com ela e volte até mim mais tarde."] = "35b8db7ba4c158e508af94c80ef204f9",
            ["Que dia maravilhoso! Me dá inspiração para criar um novo modelo."] = "8ad0f749911a3563135d77e9f55d331f",
            ["Seus talentos são imensos e você tem muita inspiração. Para continuar em sua busca por conhecimento, fale com Georgio Bolero em Ventobravo. Ele é tido em alta consideração e será capaz de lhe dar maiores instruções."] = "8fde40eee1eab031066dd85909d1ef50",
            ["Você agiu bem, viajante. Tenho orgulho em chamar você de $Gmeu:minha; aprendiz!"] = "0fb161fe21a8ff5f560e714f38fb0b44",
        },
        [4160] = {
            ["Chegou a hora de procurar alguém que lhe ensine técnicas mais avançadas. No Domínio de Plumaluna, em Feralas, vive a elfa noturna Kylanna Murmúria. Ela tem uma mente brilhante e, sem dúvida, pode lhe dar mais treinamento."] = "a6416950bbc59cd6baa28946a3f76041",
            ["Esta poção parece curar menos danos a cada vez que a preparo, embora sempre use os mesmos ingredientes. Só pode haver uma conclusão: as plantas estão se modificando. Só não posso dizer como nem em quê."] = "13119ff66e549fa7660732b19647f9bd",
            ["Seu aprendizado está evoluindo bem. Você deveria se orgulhar de suas conquistas."] = "015468259c43500419a2f50f203dbd3e",
            ["Você precisa progredir na arte alquímica antes de se tornar $Gum dos meus:uma das minhas; aprendizes. Até lá, talvez Sylvanna Silvoluna ou Milla Fairancora possam lhe ajudar, logo ali."] = "58b32f3b07654af166e55ee5ae463360",
        },
        [4163] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["Mensageiros de Corvoforte me entregaram esta carta hoje de manhã. Está endereçada a você, $n."] = "8a0abdcbc600f60a9fcf653afbc414fa",
            ["Nós somos apenas escuridão e sombras. Eternos. Invisíveis."] = "e8b964bb2f42459fd5d4d58181834b5d",
            ["Saudações, jovem $Gladino:ladina;. O que você procura?"] = "249236308a24ca006ca2a9251d3eea0a",
        },
        [4165] = {
            ["Como $Gum mago:uma maga;, você pertence ao seleto grupo que consegue conjurar um portal que lhe transportará de volta a este mesmo local. Posso lhe ensinar como, se você estiver $Gpronto:pronta;."] = "c0b64230899c1f169032e2124bab7479",
            ["Creio que você não possua a acuidade mental para compreender os mistérios da magia dos portais."] = "6169b63082c1481ee1b292a6bd277450",
        },
        [4193] = {
            ["Adoraria fazer de você $Gmeu:minha; aprendiz. Vamos começar."] = "a5bb9bf7601a2bba6b4270f85bdd04f4",
            ["Bordar exige uma mão firme. E paciência... Acima de tudo, paciência."] = "afa3c58692e1f910f1511cf81176b4cf",
            ["Está na hora de você viajar para Darnassus e falar com Me'lynn. Ela vai guiá-$Glo:la; de agora em diante."] = "2b4f7103b433f22f1e0130533daa0976",
        },
        [4200] = {
            ["Apesar da Costa Negra ser mais perigosa do que a costa de Teldrassil, muitos pescadores conseguem lucrar aqui."] = "40cb7a31eb60d273876ed5e0a23aa52f",
        },
        [4205] = {
            ["$GBem-vindo:Bem-vinda; ao Círculo Cenariano, $c. Como posso ajudar você?"] = "7dd7ee318342731a34bf5316088d4c74",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "30ee103c545f987ab518c70f6d3e640e",
            ["Não posso treinar $Gum:uma; $c como você."] = "f2c2c7d6984ce15c597fe07b1c728e29",
        },
        [4210] = {
            ["A culinária é uma atividade para toda a vida. Vejo que compartilhamos a mesma paixão!"] = "95be6f4a5e8c06f411a7922aba42f920",
            ["Encontre Shandrina no Refúgio Brisaprata. Ela pode lhe vender o 'Livro de Receitas do Perito'."] = "9530fe03acd8fd0d529479909397654b",
            ["Eu posso ensinar você a cozinhar!"] = "d8db5bcf701df43b6392f5a3b85ce404",
            ["Funesto Marrão, de Geringontzan, é um mestre das artes culinárias. Se você quiser aperfeiçoar sua técnica, procure-o."] = "39b65bdd01752b5105cbbb2683f8191b",
        },
        [4211] = {
            ["Eu posso lhe ensinar as técnicas de Primeiros Socorros."] = "d4d40db0ea32c39f6285731935893eca",
            ["O estimado Doutor Gregório Casagrande pode prosseguir com o seu treinamento. Ele fica em Theramore, cuidando dos feridos no quartel."] = "d3686c1236f20aa21b8980c23e1b8adb",
            ["Ouvi dizer que Deneb Walker tem um livro que com certeza vai te ajudar a aperfeiçoar sua técnica de Primeiros Socorros. Ele está escondido em Stromgarde."] = "f4ce78e835b2a64f849bbc3c885698a9",
        },
        [4212] = {
            ["A grama está macia e vistosa. O ar está fresco, cheio de luz e música. Tudo o que vi sugere que Teldrassil é um sonho que se tornou realidade. Por que então meu coração está cheio de maus presságios?"] = "4c3e882d5b6e6e4d3050a7dcc19f97b7",
            ["Lamento dizer que não posso ajudá-$glo, meu nobre senhor:la, minha gentil dama;, até que você aprenda mais sobre o trabalho com couro. Fale com Faldron ou Darianna, eles podem lhe ensinar as técnicas necessárias."] = "5d568f2ee6e5585a3694d234762d64af",
            ["Não tente impor seu desejo ao couro. Ao invés disso, deixe que a tendência natural dele determine que formato e função ele terá. Esta não é uma batalha para se vencer. Trabalhe com o couro, não contra nós."] = "2311acc40d0eada3baa06ec889348fc2",
            ["Você superou minha habilidade de professor. Viaje agora para o Ninho da Águia nas Terras Agrestes e fale com o anão Drakk Manopedra. O trabalho dele é magnífico, muito melhor do que o meu."] = "7461509c37eb6a03aa5e3875c4eeb8d1",
        },
        [4213] = {
            ["Belo trabalho! Você é realmente $Gmerecedor:merecedora; do conhecimento que lhe concederei!"] = "3184759a6de00367ad581b70c97d3358",
            ["Você ainda não aprendeu o básico, viajante. Já falou com minha assistente Lalina Lunestio? Talvez seja o que deva fazer."] = "3179709b6d6763d00fafe6e4d749f3e0",
            ["Você é $Gum encantador:uma encantadora; excepcional, e acho que supera meus talentos como professor. Procure Kitta Ventígnea na Torre de Azora. Somente ela tem qualificações para lhe instruir agora."] = "41da82d3c3fe92c245b041f83fe5f39c",
            ["É verdade que tenho habilidades para ensinar àqueles que são dignos. Seria você $gum deles:uma delas;?"] = "a53ae503ee886bb7a89a674e55487015",
        },
        [4214] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "30ee103c545f987ab518c70f6d3e640e",
            ["Mensageiros de Corvoforte me entregaram esta carta hoje de manhã. Está endereçada a você, $n."] = "cd9efe92b4cd73363689d342f33b4061",
            ["Não treino a sua classe, $c."] = "f7c03ed04dab075fddaf94fa5e6690d8",
            ["Saudações, jovem $Gladino:ladina;. O que você procura?"] = "359b565e3f9598b0c4c99d31465a6002",
        },
        [4215] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "30ee103c545f987ab518c70f6d3e640e",
            ["Mensageiros de Corvoforte me entregaram esta carta hoje de manhã. Está endereçada a você, $n."] = "cd9efe92b4cd73363689d342f33b4061",
            ["Não treino a sua classe, $c."] = "f7c03ed04dab075fddaf94fa5e6690d8",
            ["Saudações, jovem $Gladino:ladina;. O que você procura?"] = "359b565e3f9598b0c4c99d31465a6002",
        },
        [4217] = {
            ["$GBem-vindo, meu irmão:Bem-vinda, minha irmã;. Se você veio para treinar, então terei muito prazer em ajudar!$B$BHá boatos de dissensões no Círculo Cenariano, mas você não deve dar ouvidos a esses disparates. Nosso Arquidruida, Fandral Guenelmo, nos lidera, e a toda Teldrassil, rumo à glória!"] = "765d7c8eab15fae760b184c664fb9e9a",
            ["O que traz você ao Círculo Cenariano, $N?"] = "fb107f4dbefdbafaf3a91b5c9b3d998b",
            ["Se assim desejar, além de treiná-$glo:la;, tenho também o poder de apagar de sua mente os conhecimentos sobre seus talentos. Saiba que, cada vez que você passa por esse procedimento, ele fica mais difícil de ser realizado e, consequentemente, mais caro."] = "d8d678c1fa7a5d0ec00c8daf69cd26f9",
        },
        [4218] = {
            ["$GBem-vindo, meu irmão:Bem-vinda, minha irmã;. Se você veio para treinar, então terei muito prazer em ajudar!$B$BHá boatos de dissensões no Círculo Cenariano, mas você não deve dar ouvidos a esses disparates. Nosso Arquidruida, Fandral Guenelmo, nos lidera, e a toda Teldrassil, rumo à glória!"] = "765d7c8eab15fae760b184c664fb9e9a",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "30ee103c545f987ab518c70f6d3e640e",
            ["Que as bênçãos de Cenarius sejam suas, $c. Nosso líder, o Arquidruida Guenelmo, nos guia, e a toda Teldrassil, para uma vida renovada!"] = "04deb31038105cfd74ab05f52c151823",
        },
        [4219] = {
            ["$GBem-vindo, meu irmão:Bem-vinda, minha irmã;. Se você veio para treinar, então terei muito prazer em ajudar!$B$BHá boatos de dissensões no Círculo Cenariano, mas você não deve dar ouvidos a esses disparates. Nosso Arquidruida, Fandral Guenelmo, nos lidera, e a toda Teldrassil, rumo à glória!"] = "765d7c8eab15fae760b184c664fb9e9a",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "30ee103c545f987ab518c70f6d3e640e",
            ["Que as bênçãos de Cenarius sejam suas, $c. Nosso líder, o Arquidruida Guenelmo, nos guia, e a toda Teldrassil, para uma vida renovada!"] = "04deb31038105cfd74ab05f52c151823",
        },
        [4241] = {
            ["É uma honra abastecer os aventureiros, pois eles são futuros heróis."] = "1245860919a037af19c20e24c625c670",
        },
        [4256] = {
            ["Se tu quer saber minha opinião, não há melhor profissão do que a de minerador. E, se tu quer saber mais, não há minerador melhor do que um anão!"] = "77ab7ea3aff9f5b83ed9f444750c2f64",
        },
        [4258] = {
            ["Espero que tu não tenha vindo até a Grande Forja só para se aquecer. Fale logo, $gguri:guria;, diga o que posso fazer por você."] = "e40bd9cff0a2b475b7f856f9b06f20cd",
            ["Não tenho palavras para descrever o seu trabalho. Você faz coisas realmente incríveis com um martelo e uma bigorna. Olha, não vai espalhar que eu $go:a; aconselhei a procurar um goblin pra te ensinar, mas é isso mesmo que eu vou fazer. O nome dele é Brikk Belofício, e a última notícia que tive foi que ele estava trabalhando numa oficina na Angra do Butim."] = "c3356da865caee5c14d5f6bf59f6db2a",
            ["Sinto muito, $gguri:guria;, mas você não tem a base necessária para aprender o que eu ensino. Mas não se preocupe, vá falar com meu aluno Rotgath, ele pode te ajudar."] = "ae2d32ca31d33d2e9a8717028c168fb8",
            ["Você tem cara de $Gferreiro:ferreira;. Fuligem debaixo das unhas, aço nos ossos. Isso, tem sangue de $Gferreiro:ferreira; nas veias. Ou seja, tu veio me procurar pra aprender uma coisa ou outra... Bem, $gguri:guria;, pega um martelo. Vejamos o que posso te ensinar."] = "6d836253374e7258f1d26abac7475d18",
        },
        [4262] = {
            ["A Guarda de Lançatroz precisa de você na luta contra o Clã Lobo do Gelo, $n. Vá falar com Brogun Escudopétreo no Terraço dos Guerreiros e ele lhe indicará o caminho do Vale Alterac. Eluna seja louvada!"] = "a3be30c0db4f2d4b202783dd948834c7",
            ["A empreitada em que você embarcará não será fácil, $n. Para chegar à Ravina Brado Guerreiro, você terá de falar com Aethalas, a Mestre de Batalha das Sentinelas da Asa de Prata. Ela guiará seus passos. Vá com Eluna!"] = "6fb5236e00160c864eb6347215bab509",
            ["A habilidade com que Telonis faz armaduras não tem comparação. Você deveria ficar $Ggrato:grata; por ele não cobrar mais pelo conhecimento que passa aos outros. Vá procurá-lo no Terraço dos Artesãos na parte nordeste de Darnassus."] = "460a90211acc699941f3d86d6b4ff971",
            ["Abriram uma dessas no Terraço dos Mercadores. Se você seguir o caminho do sudeste, a partir do banco, vai encontrá-la fácil."] = "9053576b60544f166b688a294bcea667",
            ["Ah, a constante obsessão pela riqueza material. Bem, a sorte lhe sorri, já que você pode encontrar a casa de leilões no Terraço dos Mercadores."] = "d90f95e047a57954e455f354c946ef06",
            ["Alegorn é um chefe magistral, que passou séculos aperfeiçoando a arte culinária. Você considere uma bênção caso ele decida lhe ensinar. Se você acredita ser $Gdigno:digna;, poderá encontrá-lo no Terraço dos Artesãos."] = "ed3705061b45f850ff33561c67657b78",
            ["Aqui em Darnassus temos instrutores hábeis, que se aperfeiçoaram nas artes de cada classe ao longo de anos de treinamento e dedicação. Vou levar você até um que possa ser seu mentor, mas você precisa dizer qual é o caminho que escolheu."] = "05f41dc20d172bc58dcbca463c852a7a",
            ["Aqui, entre os artesãos de Darnassus, há um milênio de conhecimento para o benefício de seu ofício de escolha. Agora, diga-me, qual arte você acha mais fascinante?"] = "b653ff673ce5e58760ed8282427e63d7",
            ["As vestimentas que Me'lynn costura dão a impressão de que a agulha dela foi abençoada pela própria Eluna. A menos que sua agulha seja igualmente abençoada, recomendo que você a visite e escute seus ensinamentos. Você vai encontrá-la no Terraço dos Artesãos, na região nordeste de Darnassus."] = "df79484b5472d76db96b41898d02b9b7",
            ["Astaia catou alguns tesouros curiosos ao longo de tantos anos de pescaria. Por que você não vai visitá-la no terraço dos Mercadores e pede para ver alguns?"] = "bd5332cda23cfb988a28235b91583693",
            ["De todos os lugares maravilhosos em Darnassus, para qual você deseja ser $Gencaminhado:encaminhada;?"] = "5f49a0ce5b3654379f0db519a20b64a4",
            ["Em tempos difíceis, um druida pode ser um bom amigo para aqueles que o cercam. Pergunte a qualquer druida do Enclave Cenariano e ele lhe dirá o mesmo."] = "f818dab29f5921c495fafd0e54c105fe",
            ["Embora eu ache a grama que cobre Teldrassil uma cama tão boa quanto qualquer outra, as camas que Saliennte tem na estalagem no Terraço dos Artesãos são adequadas para aqueles com um gosto pelo luxo."] = "5573d0a9c052f20b0f5fb6476dc53256",
            ["Ervas e a coleta delas são especialidades de Firodren Clamaluna. Procure-o nos Jardins do Templo, na área sudoeste de Darnassus."] = "1e49a3cf6e73b8db88f365f3278429d3",
            ["Eu sei de quem você está falando, $c. Procure por Brogun Escudopétreo no Terraço dos Guerreiros."] = "fde3cbd79786d9234392c6be3a040901",
            ["Graças a Eluna! Você procura a Mestre de Batalha da Ravina Brado Guerreiro? Ela se chama Aethalas e fica perto dos instrutores de guerreiros."] = "3b431228797b39bb81cdc82774f643d5",
            ["Há centenas de anos os animais que ajudam nossos caçadores receberam cuidados de Alassin. Ele é bastante considerado pelos caçadores das redondezas. Se você quer encontrá-lo, procure no Enclave Cenariano."] = "417a4e706b4f46ae4fb091d34eec2534",
            ["Há muitos que tentam seguir o caminho dos Ladinos, mas apenas os elfos noturnos são verdadeiramente acolhidos pela noite. Se você deseja andar por este caminho das sombras, então procure Syurna no Enclave Cenariano."] = "9955006745f984da2926e3193c72c1bf",
            ["Há vários campos de batalha. Para qual você deseja ser $genviado:enviada;?"] = "bc8107859019ab2e37a4c010332b9f07",
            ["Jocasta foi a maior caçadora da época dela. Hoje em dia, ela fica no Enclave Cenariano, onde ela dá aulas para os caçadores iniciantes."] = "00076a2f6e55d2922d9773ef70577aa5",
            ["Lysheana vai lhe fornecer os documentos adequados. Ela mora no Terraço dos Artesãos, na parte nordeste de Darnassus. Que sua irmandade traga glória para os elfos noturnos!"] = "3eb0dbc4dec391944ba49aa445235c37",
            ["Mais $gum:uma; consumista, não é? Bem, se você é $gobcecado:obcecada; pelos seus preciosos itens, então provavelmente vai querer guardá-los no Banco de Darnassus, no centro de nossa cidade."] = "c45c7553069860089340adb456de7764",
            ["Na morte, os animais do mundo nos concedem tanto vida quanto proteção. Se acha que pode oferecer o respeito adequado pelo sacrifício deles, então, a profissão de esfolador pode combinar com você. Fale com Eladriel no Terraço dos Artesãos em Darnassus para aprender mais."] = "d56f05ee073017a9143e842d802a0700",
            ["Nosso povo não acredita em desperdício. Quando somos forçados a matar uma criatura, tiramos tudo que podemos, para garantir que o sacrifício não tenha sido em vão.   Se você quer aprender a maneira apropriada de tirar a pele de uma fera abatida, então, procure Eladriel no Terraço dos Artesãos."] = "c96f29161dcade9647c6f8707b27e20c",
            ["Nós plantamos as verduras. Nossas verduras são comidas pelo coelho. O coelho é devorado pelo lobo. O lobo é morto por nós. Nós pegamos a carne e a pele do cadáver do lobo. É o mágico Círculo da Vida, ou sei lá que nome você queira dar.   Agora vá procurar Telonis no Enclave Cenariano e deixe-me voltar às minhas obrigações."] = "86a6b22447f3864053114200f5749bbf",
            ["O Templo da Lua é o lar das sacerdotisas de Eluna. Lá, você encontrará Jandria e Lariia, que lhe fornecerão orientação adicional no caminho do sacerdócio."] = "5963595e8e789ae76d21d76349020da9",
            ["O sol já nasceu? A noite tem horas de menos na minha opinião! Bem, Saliennte vai cuidar direitinho de você. Ela recebe os clientes lá no Terraço dos Artesãos, na parte nordeste de Darnassus."] = "4a2ffe6ddb889c11783a240b6fbb5753",
            ["Obrigada, é gentileza sua, mas já sou compromet... Quê? Ah, você quer SER $gencantador:encantadora;? Ai, que vergonha! Bem, você tem que... você pode... falar com... hum... Taladan! Isso, vá falar com Taladan no Terraço dos Artesãos! Ele pode treiná-$glo:la;."] = "8efec801651f3192ea4b39d9178f4ff8",
            ["Ora, ora. Temos aqui $Gum:uma; herborista desabrochando. Seria muito bom se você visitasse Firodren Clamaluna nos Jardins do Templo. Ele deve ter alguns truques do ofício para lhe passar."] = "ffcf7d3fc05ebc9a1303d2c59a697fcc",
            ["Os hipogrifos de Vesprystus levarão você rapidamente ao seu destino. Procure-o na Vila de Rut'theran, através do portal da parte oeste de Darnassus."] = "6d0616990747b3cf281cc9641375724d",
            ["Os humanos precisam de toda a ajuda que pudermos prestar na Bacia Arathi. Fale com Keras Coração de Lobo e ele $Go:a; ajudará. Ele fica no Terraço dos Guerreiros."] = "6307e625367c135b351d633c760f9a2e",
            ["Os pratos que Alegorn prepara desmancham na boca. Ele está sempre ocupado cozinhando novas iguarias lá no Terraço dos Artesãos. Não deixe de experimentar o Verde Cenariano que só ele sabe fazer.   Agora, se não se importa, preciso investigar o desaparecimento de cervos."] = "7a065b152cd98b50e6ec1647535c2bc0",
            ["Por milênios a fio, Ilyenia Flameluna dominou numerosas armas e agora oferece treinamentos sobre o uso delas. Se quiser ser treinad$Go:a;, procure-a no Terraço dos Guerreiros."] = "9a3ffcf5f60258c99f20760ca3d68d55",
            ["Procure Syurna se quiser seguir o caminho dos ladinos. Ela está no Enclave Cenariano, no fim do caminho em espiral na árvore mais a oeste."] = "75e196ec78d6cb7a83a96b0b2894c9b7",
            ["Quando não se tem um curador para cuidar de seus ferimentos, o conhecimento de Primeiros Socorros pode salvar sua vida. Eu consultaria Dannelor lá no Terraço dos Artesãos para obter instrução nessa habilidade."] = "6fd835875fbe8020422ad312f515153d",
            ["Quer um alquimista? Sem problema, $c. Ainethil, graças a todo o trabalho e esforço, tornou-se a alquimista mais talentosa no Terraço dos Artesãos. Se eu fosse você, iria até lá imediatamente. Imediatamente! Agora, suma daqui!"] = "dd479dae533f32a3992c77a3d1aa7f7e",
            ["Recebi a maior parte do meu treinamento com armas de Ilyenia Flameluna no Terraço dos Guerreiros. Vá procurá-la se quiser aprender a usar uma nova arma."] = "3fdb5882d52420a10cedda5c6704aa3b",
            ["Se quiser formar uma sociedade, então é com a mestre de guildas Lysheana que você deve falar. Você vai encontrá-la no Terraço dos Artesãos, na seção nordeste de Darnassus."] = "36a062f0dc1636d9af51d4236918fc7a",
            ["Se você realmente tiver vontade de aprender esse ofício, eu lhe indico Ainethil, uma experiente alquimista no Terraço dos Artesãos, no norte de Darnassus."] = "92c77d24eda0e89d883523e9617dfaab",
            ["Se é isso que quer, $c, então você tem que falar com Keras Coração de Lobo no Terraço dos Guerreiros. Ele representa a Liga de Arathor e $Go:a; ajudará a chegar na Bacia Arathi."] = "f59a17baa98d87d57ad047e9e528c0a0",
            ["Sempre vigilantes a proteger a natureza, os druidas são guiados pelo Arquidruida Fandral Guenelmo, que mora no Enclave Cenariano. Você o encontrará, assim como outros instrutores druidas, na ala norte de Darnassus."] = "1050e24a7181b4781e75952eb85b3d9a",
            ["Sildinair fica em meio aos guardas no Terraço dos Guerreiros, com os olhos vivos buscando na floresta inimigos que possam ousar entrar na nossa bela cidade."] = "f44318c049c218b57b0e409073bd7f96",
            ["Sildinair treinou muitas das Sentinelas que protegem nossa amada cidade. Tenho certeza de que ela pode transformar pessoas como você em guerreiros. Procure-a no Terraço dos Guerreiros, perto da entrada de nossa cidade."] = "2fe98252b42a97d60efb568891e47919",
            ["Sorte sua ter vindo para Darnassus, onde você pode encontrar uma caçadora tão talentosa quanto Jocasta entre nossos instrutores. Eu encorajo você a visitá-la no Enclave Cenariano e a pedir a tutelagem dela."] = "d15a97ec9abacddad8435f5774a0eb2c",
            ["Só Eluna expulsa demônio das pessoas! Só Eluna expulsa demônio das pessoas!   Agora, vá! Procure Jandria no salão central do Templo da Lua, que fica na parte sul de Darnassus!"] = "fe788e668631819d89ea6f47c42c2f9e",
            ["Tem uma caixa de correio em frente ao banco, no centro de Darnassus."] = "f051b310bb2a6de52b45a40b67fd3a3f",
            ["Uma caixa de correio? Você tem alguma carta para mandar ou, talvez, para receber? Espero que seja algo bom! Tem um caixa de correio diante do banco, no centro de Darnassus."] = "4f8593ba9dc0933eabfbe1601c8a4af6",
            ["Uma espada nunca é afiada o bastante, nem uma armadura resistente o suficiente, por isso, um encantador habilidoso será sempre necessário. E esse encantador é Taladan, que pode mostrar como tecer encantos corretamente para aperfeiçoar suas armas e armaduras. Procure-o no Terraço dos Artesãos."] = "244792d6c2e0f82f39ae6c0a4b8bc872",
            ["Uma habilidade que consome tempo, mas é gratificante. Fale com Astaia no Terraço dos Mercadores e, talvez, você aprenda alguma coisa útil."] = "04597ac6ff8258c56c07b668a4c288ac",
            ["Você certamente procuraria Me'lynn se tivesse alguma esperança de aprender a ser $Gum:uma; alfaiate. Ela mora no Terraço dos Artesãos na parte nordeste de Darnassus."] = "244b2695394eae58d2ff7f21af8ec998",
            ["Você pode armazenar seus bens materiais no banco de Darnassus. Ele fica no centro de nossa maravilhosa cidade."] = "8eb9ba45b797263e4803382aebcf7ae3",
            ["Você pode confiar qualquer uma das suas feras a Alassin, que ele cuidará bem dela. Ele mora no Enclave Cenariano, onde os caçadores se reúnem."] = "59d50b4f9dac8cf71ca0cfbdeaec5833",
            ["É Vesprystus que você procura. Ele cuida dos hipogrifos que vão e vêm da base de Teldrassil. Para chegar nele, atravesse o portal na parte oeste de Darnassus, que $go:a; levará à Vila de Rut'theran."] = "21666b1c2ab2afe583fd533d9f03402b",
        },
        [4267] = {
            ["Para onde deseja voar?"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [4312] = {
            ["Para onde deseja voar?"] = "008491a7c8f31e3556f00e8c3fdc3190",
        },
        [4314] = {
            ["Eu vou ficar aqui até pescar uma Garoupa de 34 Quilos! Você, por outro lado, quer voar para algum lugar, não é mesmo?"] = "618fd179dc62675047c361ba163020cb",
            ["Não está vendo que estou pescando?!"] = "6d360eae76ce9d8dd443dda348dde45e",
            ["Que posso fazer por você, $c?"] = "8954aa5e093a20511ce5bc5c69380aac",
            ["Você afugentou os peixes! Que você quer?"] = "fdcd1e64bf065be3a6c23042d93a5b68",
        },
        [4317] = {
            ["Para onde deseja voar?"] = "26d3fb863cf374254276fad4c4fb1b43",
        },
        [4319] = {
            ["Para onde deseja voar?"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [4320] = {
            ["Sinto muito, $gmeu amigo:minha amiga;. Eu só ajudo caçadores e as feras deles."] = "963db5ef5555edf879e137a605643024",
            ["Você veio adquirir treinamento para as suas feras?"] = "3108806b44f37624987d36cafc8de658",
        },
        [4321] = {
            ["Para onde deseja voar?"] = "646a52da6f00e2b6b680741da2aab13f",
        },
        [4407] = {
            ["Para onde deseja voar?"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [4419] = {
            ["$GBem-vindo:Bem-vinda; às corridas! Aproveite a estadia e não aposte todo o seu dinheiro em um só lugar!"] = "3fda9ba9ead86b9e29b7d1fc68875623",
            ["O Depenado não quer que o Tirth saiba que ele ainda está na Chapada Cintilante, por isso se transformou num frango!$B$BSe você encontrar o Depenado, chame-o. Talvez ele saia do esconderijo."] = "818428d85cc2451411dffed3878e6204",
            ["O piloto goblin tem muita garra, mas os gnomos esconderam um ou dois segredos no carro deles..."] = "85279dcb34b8519c4aa585d439098471",
            ["Olá, $c! $GBem-vindo:Bem-vinda; às corridas da Chapada Cintilante!"] = "cf552d2d1ba02525e8fcd3e41003294d",
            ["Quem tem o carro mais veloz? Quem sabe?!?"] = "f8abb3ccf31041b3183d41a1896f28e3",
        },
        [4429] = {
            ["Ah, está falando do Johnson? Soube que ele está escondido."] = "38a01b6277bccedcf3bd8f0506a44706",
            ["Eu soube que eles iam tentar explodir o carro gnômico na próxima corrida! Verdade ou não, eu ficaria longe dos boxes."] = "0c2296859db21b24eb9910aa4b0c2053",
            ["Hah! Há dias que Tirth o procura, mas ele não quer ser encontrado. Ele está apavorado!"] = "4cf39f0b48e67e4fb4e5d3538ae49f07",
            ["Meu dinheiro está nos goblins! E se você tem juízo, o seu também está!"] = "8a6ae51d27ab952a233cd6f757870376",
            ["Se eu fosse você, compraria um cupom de corrida goblínica. Torcer por outro time é perda de tempo."] = "84067fc993444ce72a27b52f4f74bec4",
            ["Se não fosse por aquela maldita sorte gnômica, eles nunca venceriam uma corrida!"] = "1707d93334e41f8adae340c8be1bc91a",
            ["Se quer minha opinião, os goblins são a escolha mais óbvia. Temos as ferramentas e temos o talento!"] = "ef38b09c14f46b5a8dcf5d782c630fd6",
            ["Você está procurando Depenado? Bem, você não me ouviu falando isso, mas... se você perguntar para Kronrider lá em cima na torre, talvez ele conte a você..."] = "6ca0e5f286f5115ccba86010cc9d19a7",
        },
        [4430] = {
            ["De acordo com o meu Geringótico Almanacotrom, a gente vai ganhar dos goblins por uma vantagem de vinte segundos a mais do que a última vez!"] = "29cb9f241b67a6bd58f46757f27f6f9e",
            ["Depenado? Ouvi falar que o Mestre de Corridas Kronrider, lá na torre, sabe onde ele está."] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
            ["Essas corridas são uma grande oportunidade de mostrarmos a nossa engenhosidade!"] = "88d6d4700d0a9435deac731bbef17f8c",
            ["Instalei um novo aparelho no regulômetro matriz do nosso carro. Isso deve aumentar o quociente de velocidade por um fator de no mínimo quinze!"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
            ["Meu filho conseguiria projetar um carro mais veloz que aquela pilha de sucata goblínica malfeita!"] = "5a9bf6255acd34e980aebcd04a7a6def",
            ["O Johnson? Acho que ele está por aqui..."] = "5d227c61a514e3f0b41f912efe022c52",
            ["O Tirth não anda nada bem, nem o assistente dele."] = "329639fd7e8c50ac0b798afe6c0f563e",
            ["Se não fosse pela inacreditável sorte dos goblins, eles bateriam o carro em todas as corridas, sem exceção!"] = "413ec8412f752d13ea7d3bc09e39592d",
        },
        [4488] = {
            ["Agora me responda uma coisa, $n$BQue criatura se tornou o Lich Rei antes de espalhar a peste por Lordaeron?"] = "f6f7ba02da1200cdb9a4345823966550",
            ["É sempre bom quando alguém deseja falar comigo. Como andam as coisas, $c?"] = "b219a709c06746dd4308b42ceae14a51",
        },
        [4489] = {
            ["Minha pergunta para você é a seguinte, $c:$B$BQual dos Aspectos criados pelos titãs se tornou a criatura abominável conhecida como Asa da Morte?"] = "8a2e3ce00848461a788a1c12e87e9577",
            ["Saudações, $c. Há algo em que eu possa lhe ajudar?"] = "06ed16ee9dc4b0c6ba6d2eea8e2d58cc",
        },
        [4542] = {
            ["<O alto-inquisidor Fairbanks Nega com a cabeça.>$B$BNão, $r, somente um dos filhos dele está morto. O outro está vivo...$B$B<O alto-inquisidor Fairbanks aponta para o céu.>$B$BTerralém... encontre-o lá..."] = "0405e4235c3c4375d54a46badf6f9a18",
            ["<O alto-inquisidor Fairbanks assente.>$B$BÉ, o jovem Mograine, conhecido como Comandante Escarlate, por meio do pacto do Grande Cruzado – suspeito eu – conduziu o pai à emboscada como se conduz um cordeiro ao matadouro."] = "c6b0e8d92e327360ee6e22abe88e74a0",
            ["<O alto-inquisidor Fairbanks levanta o tabardo, revelando várias cicatrizes repulsivas.>$B$BEu estava lá... eu era o conselheiro do Grão-lorde em quem ele mais confiava. Eu devia saber... eu senti que havia algo de errado e ainda assim deixei que tudo aquilo acontecesse. Você acreditaria se eu dissesse que havia mais de mil homens do Flagelo?"] = "51188fc10a87cced513453708b5ed8eb",
            ["<O alto-inquisidor Fairbanks nega com a cabeça.>$B$BNão... ele ficou lá longe, assistindo à legião de mortos-vivos que se abatia sobre nós. Pouco depois, eu estava exausto. Fui o primeiro cair... com certeza eles teriam me esquartejado, membro por membro, enquanto eu jazia inconsciente... mas eles me ignoraram, concentrando-se no Grão-lorde."] = "8dc3c54670f0b069274f87a57d834908",
            ["A lâmina e Mograine eram uma única entidade. Entende? A traição corrompeu a lâmina e levou à corrupção de Mograine, tornando-o um cavaleiro da morte de Kel'Thuzad. Eu jurei que, se eu sobrevivesse, iria expor os perpetradores desse crime hediondo. Por dois dias eu fiquei sob a podridão do Flagelo, reunindo as minhas forças como pude para escapar da cidade arruinada."] = "53ad3252b278c0ae93d1b6b40ce3adc1",
            ["Como somente os heróis podem morrer, $r: numa tragédia. O Grande Cruzado fez um pacto com ninguém menos que Kel'Thuzad! Seria armada uma emboscada que resultaria na morte de Mograine. O tipo de traição que só poderia resultar das ações de um companheiro querido e confiável."] = "351782cc2c2eab075255b02928b70aab",
            ["Este homem era o Calcinador, $Gtolo:tola;! Enquanto o Flagelo se materializava à nossa volta, a lâmina de Mograine começou a brilhar... a gemer... O jovem Mograine tomou isso como um sinal para escapar. Eles se abateram vorazmente sobre nós como eu nunca vira. E ainda assim..."] = "8e73eebbc5846e6d2b35af2153300f68",
            ["Finalmente, a maldição se desfez. Obrigado, $Gherói:heroína;."] = "3146d1e3ce619ce4be9719884bfd59d3",
            ["Foram a general-de-exército Abbendis, o alto-inquisidor Isillien e o grão-lorde Mograine que formaram a Cruzada. No início, a Cruzada era um ordem nobre. A loucura e o fanatismo doentio que se vê hoje não existiam. Foi apenas com a chegada do Grande Cruzado que se acionaram as engrenagens da corrupção."] = "49e8b244faaa788e192bdbf757290769",
            ["Não bastou.$B$B<Fairbanks sorri num esgar, perdido numa lembrança.>$B$BMil vieram e mil tombaram. Pela Luz! Pelo poder de Mograine! Ele os derrubava na mesma velocidade em que eles chegavam. Em meio ao caos, notei que o jovem Mograine ainda estava lá, ao longe. Gritei para ele: 'Ajude-nos, Renault! Ajude o seu pai, garoto!'"] = "e174ab34785ee68b6e6d0710eca52df1",
            ["O Grão-lorde era o eixo da Cruzada. Mograine recebeu a alcunha de 'o Calcinador' devido às façanhas que realizava contra os exércitos do Lich Rei. Armado apenas de sua lâmina e de sua fé, Mograine se lançava contra batalhões inteiros de mortos-vivos e emergia ileso – o único indício de que ele havia lutado eram as cinzas dos seus oponentes. Você não compreende? Na presença dele, até mesmo a morte tremia de medo!"] = "5d26127991e8911d63d93013418dcde7",
            ["O garoto pegou a Crematória e trespassou o peito do pai enquanto ele estava de costas. As últimas palavras dele me assombrarão para sempre: 'Que é isso, Renault? Por quê?'"] = "bec302f02e2201f067255a714e311fff",
            ["Quer dizer que você não sabe? A espada que você carrega nas costas se chama Crematória, cujo nome adveio de seu primeiro dono."] = "5305da0d8750979d1bc134fec6194486",
            ["Receio que a lâmina que você tem em mãos não tenha mais salvação. O ódio está muito arraigado nela. Mas não perca a esperança, $c. Ao término de um capítulo, outro se inicia.$B$BEncontre o filho dele, o homem mais virtuoso e devotado que você jamais viu. Dizem que ele é capaz de forjar uma nova Crematória sem precisar da antiga lâmina maculada."] = "2ec9cfd31d00a8b0299dc181a8190cd6",
            ["Tudo o que eu pude fazer enquanto as carcaças do Flagelo se empilhavam sobre mim foi fingir que estava morto. Só havia escuridão e os sons abafados da batalha. O colidir do ferro, o triturar dos ossos... um terror, sons horríveis. E então, o silêncio. Ele me chamou: 'Fairbanks! Fairbanks, cadê você? Fale comigo, Fairbanks!' E, finalmente, o som da incredulidade. A apunhalada traiçoeira, $r..."] = "f95886b49c3b646b540936a1c253acc0",
            ["É, consegui. Para a infelicidade do jovem Mograine, eu consegui voltar ao Monastério Escarlate. Eu bradei e gritei. Contei a história a todos que estivessem dispostos a escutá-la. Por causa das minhas ações, fui assassinado e arrastado para esta câmara: um segredo obscuro da ordem. Mas algumas pessoas me ouviram... sim, elas me ouviram. Assim nasceu a Aurora Argêntea..."] = "91edc5312c9d7985a58d5ec06e446c8b",
            ["É, o grão-lorde Mograine, fundador da ordem original da Cruzada Escarlate. Cavaleiro de fé e pureza inabaláveis, Mograine seria traído pelo próprio filho e morto pelas forças de Kel'Thuzad em Stratholme. Foi assim que vim parar aqui..."] = "ef7daa42b41400a1595d39af4a6e8762",
        },
        [4551] = {
            ["Como posso ser útil?"] = "7c8c7304e2aa7ceedcd878cb5540437f",
        },
        [4552] = {
            ["A culinária é uma atividade para toda a vida. Vejo que compartilhamos a mesma paixão!"] = "f5400ec6ebea670b036a6880beada4ab",
            ["Eu posso ensinar você a cozinhar!"] = "02987be90f767850ec8e9f572adbc4ed",
            ["Funesto Marrão, de Geringontzan, é um mestre das artes culinárias. Se você quiser aperfeiçoar sua técnica, procure-o."] = "9f8ebedd06a040d3d2ffa50aac35d51f",
            ["Wulan, da Aldeia Pescassombra, pode lhe vender o 'Livro de Receitas do Perito'. Se você quiser se aperfeiçoar, terá de ler esse livro."] = "fc64c85b44749257ced7e34a940a1c64",
        },
        [4556] = {
            ["Saudações e boas-vindas. Não sou muito de sorrir, mas acredite: fico feliz em lhe servir."] = "f036f024de84a7992c236bf86b742eab",
        },
        [4563] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "3a364a4573d4825a6795e3bb454069d4",
            ["Sua vontade não é forte o suficiente para manipular as forças que controlamos, $c."] = "5a92f47cf481eb3def2615b8693c94fc",
            ["Você sabe o bastante para oferecer perigo mas, para mim, ainda parece que precisa de treino, $n."] = "f097ab331f582c2d79e805e164a7c169",
        },
        [4564] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
