        [5173] = {
            ["As trevas não aceitam você, $c. Acabe com essa ladainha e saia da minha frente! Vá!"] = "c4bef13520e7f7e2f4078fbe96c02345",
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["O arcano só corrompe os fracos. Continue treinando, ou poderá ter um destino semelhante."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
        },
        [5174] = {
            ["As coisas que eu te ensinaria transformariam teu cérebro em gelatina! Volte quando tiver aprendido o suficiente."] = "b755b1fc6301fcee6cdc7c58adc7f319",
            ["Com certeza você evoluiu bastante em seu treinamento. Só tem uma pessoa capaz de continuar a treinar você: Zumbo Dobradiço, de Geringontzan!"] = "7fd261ac07f2ec746da51fd338facc6e",
            ["Excelente, tu provou que tem valor! Agora vamos para a próxima fase de seu aprendizado..."] = "3f10866c8c4a33701d0af2dbef824694",
            ["Se meus cálculos estiverem corretos, a roda se tornará obsoleta em pouco tempo!"] = "5b4916cbd8099a80750c2e7c7f7d81f4",
        },
        [5177] = {
            ["Hum... você já sabe tudo que eu podia te ensinar. Talvez seja hora de você falar com outra pessoa. Procure a elfa noturna Ainethil no Terraço dos Artesãos de Darnassus. Ela é muito talentosa!"] = "416d59f7e84fada2d7ba5a58b0b3e31b",
            ["Joia, $n! Vai lá mostrar pro Vosur o que quer que seja isso. Ele vai esclarecer todas as suas dúvidas."] = "8f23541b759a735d8ee3accc858d1404",
            ["Não deixe que os olhos esbugalhados e a barba desgrenhada enganem você. Vosur é um aprendiz talentoso e bom amigo, mesmo quando fico com torcicolo de tanto falar com ele."] = "a79e427c44bffd7d2933367144381ca5",
            ["Quem é você e por que me enche a paciência? Ah, sim... está estudando poções. Tá bom. O que posso fazer por você?"] = "dd98674cdc2a54825779c2cb39041234",
        },
        [5193] = {
            ["$GBem-vindo:Bem-vinda; ao Registro de Guildas de Ventobravo. Como posso ajudar?"] = "597ed139334da6a50351437c63a259fd",
        },
        [5411] = {
            ["$GBem-vindo:Bem-vinda; a Tanaris, $n. Como posso ajudar? Você não me parece $Gum ferreiro:uma ferreira;, mas eu sei como as aparências enganam."] = "c6a4de2224006b677c95b27def90d917",
        },
        [5479] = {
            ["Com um retreinamento rigoroso eu tiro da cabeça dos meus alunos tudo que haviam aprendido antes, para poder lhes ensinar coisas novas. O serviço que presto torna-se mais difícil cada vez que é refeito. Portanto, cada novo retreino fica mais caro. Você deseja que eu tire da sua cabeça o que você aprendeu?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["Só pela sua postura, vejo que não é $Gnenhum guerreiro:nenhuma guerreira;.$B$BPor que não vai fazer alguma coisa segura, como ler um livro?"] = "8493fe09c36205db0684a4321f2d5dcf",
            ["Ventobravo é o esteio da raça humana, mantida através da força de vontade e da ponta de uma lâmina afiada."] = "0a37426688f72de523d491b07d11f473",
        },
        [5480] = {
