        [15797] = {
            ["O segredo por trás do poder dos Colossos pode levar a todo tipo de inovações na ciência!"] = "789dcc606ef711b511ee12ddff2c8186",
        },
        [15798] = {
            ["O estudo e compreensão dos Colossos nos dará uma vantagem vital contra os qirajis."] = "ca9c2a76280fa526355a744dfbdacd34",
        },
        [15799] = {
            ["Precisamos descobrir o que os qirajis dão de comer para esses monstros! Olha só o tamanho deles!"] = "392d38d469784b0930ac72d8954f8d8e",
        },
        [15864] = {
            ["Agouro repousa nas profundezas do Lago Eluna'ara, mas é possível evocá-lo da margem sudeste, perto dos Templos de Tempesfúria. Lá você encontrará lançadores de salvas de fogos especiais...$B$BUse os seus foguetes nos lançadores e os lacaios de Agouro virão. Lance mais foguetes, umas três dúzias, ou então lance as velas de Eluna contra os lacaios dele e não demorará até Agouro despertar."] = "8380da37ec60070f5cc0417fd12e3bc6",
            ["Honrar os anciãos é honrar o povo e sua cultura, $c. As moedas dos ancestrais servem como um meio tangível para reconhecer os que escolheram seguir o venerável caminho do respeito.$B$BDurante o Festival da Lua, você terá a oportunidade de honrar vários anciãos e, ao fazê-lo, adquirirá moedas dos ancestrais. Traga-me as moedas e eu recompensarei seu empenho com uma seleção de itens raros."] = "5ff684abf73ab59dca0e0d04d8c6f804",
        },
        [15871] = {
            ["Agora é a hora em que o ano ainda é jovem e a lua brilha forte.$B$BÉ a nossa hora... a hora em que despertam os ancestrais."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["O Ancião Malhogrito se encontra dentro da muralha de Ventobravo."] = "24e765cdee4370c4b56804eb47e7701f",
            ["O ancião Açolesto vaga pelas ruas de Darnassus, no alto da Teldrassil."] = "7b97edf23dc2c013612ec1169de003d7",
            ["O ancião Bandaferro mora na Caverna Calcinar, em Garganta Abrasadora."] = "6954eeb9a527a8cef8cc62722874280a",
            ["O ancião Poçodouro passa seu tempo na vila de Kharanos, em Dun Morogh."] = "11ccf478d11d91ad3de1ce0965dd1e7c",
        },
        [15895] = {
            ["Saudações, $n. Viemos da Clareira da Lua para espalhar o espírito do Festival da Lua por todos os lugares.$B$BPor que você não vem celebrar conosco?"] = "aa03e1f2960fa0bfc11594e3485ca65b",
        },
        [15900] = {
            ["Saudações, $n. Viemos da Clareira da Lua para espalhar o espírito do Festival da Lua por todos os lugares.$B$BPor que você não vem celebrar conosco?"] = "8c264afdfd859dd75aa92958ab0ec315",
        },
        [15903] = {
            ["Primeiro eles me falaram: 'bom trabalho no esforço de guerra!'. E depois: 'você será promovido!'. Mas acho que o que eles queriam dizer era 'você ficará na entrada de uma colmeia lotada de insetos, em Silithus, junto com um monte de anões suados e fedorentos!'...$B$BMaravilha de promoção...!"] = "668e49c17df4b9aa59370244f97c3f6a",
        },
        [15905] = {
            ["Após a exibição de fogos de artifício, eles nos entregarão cálices para um brinde!"] = "6d7a0a461e2650661f34cbb62df4a64c",
            ["Não sei o que colocam nesses barris, mas desce que nem mel!"] = "73bf520ba54e6d1e7f123875ac134dc2",
            ["Não vá embora antes de ver a próxima exibição de fogos – de hora em hora, a partir das 18h!"] = "9e44a7a2990575244bfb03e10d9172dd",
            ["Salve, amig$Go:a;!"] = "229605db995a9c242cc65986e5928a1b",
            ["Seria ótimo dar uns beijos agora. Sabe onde posso conseguir?"] = "4bf540b1bbdebcaec03285d831690899",
        },
        [15906] = {
            ["Após a exibição de fogos de artifício, eles nos entregarão cálices para um brinde!"] = "ed03fb23ae16fb04599c13080c1acffe",
            ["Não sei o que colocam nesses barris, mas desce que nem mel!"] = "8667d501338eab68c0b14814dab835dd",
            ["Não vá embora antes de ver a próxima exibição de fogos – de hora em hora, a partir das 18h!"] = "9946d1873a48e8fbc8fac8ab278eb276",
            ["Salve, amig$Go:a;!"] = "43ccb729b1ae428d1ed345812ed65bd0",
            ["Seria ótimo dar uns beijos agora. Sabe onde posso conseguir?"] = "bafd33062e7a5ef7f88bd3ac468a4a2e",
        },
        [15907] = {
            ["Os barris estão cheios de cerveja forte! Beba e comemore, $gmeu amigo:minha amiga;!"] = "06f49d9f9d5fb1edcf209836d4309855",
            ["Os fogos serão lançados a partir das 18h do rochedo mais alto da cidade!"] = "c5f7e2df05ba63b220570cf049a0ae7a",
            ["Ouvi dizer que, depois dos fogos de artifício, vão colocar taças nas mesas. Serão brindes fabulosos!"] = "ed962dfa7d7188507f9a08ba0eb16209",
            ["Salve, $c! Seja bem-$gvindo:vinda; à festa!"] = "82e1f388e3d1053dc0d340f63090e225",
            ["Seria ótimo dar uns beijos agora. Sabe onde posso conseguir?"] = "e46a99e660cce12f8a4292fdb7f7bc29",
        },
        [15908] = {
            ["Os barris estão cheios de cerveja forte! Beba e comemore, $gmeu amigo:minha amiga;!"] = "a1266790d643e961d1a1d9572db705d7",
            ["Os fogos serão lançados a partir das 18h do rochedo mais alto da cidade!"] = "1732c988c271232a750d3e2e53c1d1d6",
            ["Ouvi dizer que, depois dos fogos de artifício, vão colocar taças nas mesas. Serão brindes fabulosos!"] = "c6b790a30cea1e9602b2204c2fdef80a",
            ["Salve, $c! Seja bem-$gvindo:vinda; à festa!"] = "9031ad552c6f16d0a461e40e557acbd7",
            ["Seria ótimo dar uns beijos agora. Sabe onde posso conseguir?"] = "25be0d84e393ee3ed1191d398a602628",
        },
        [15909] = {
            ["Eu, assim como meu irmão, honro aqueles que honram os seus ancestrais. Fico feliz de compartilhar meus segredos com os discípulos do Festival da Lua."] = "63da9bd89a3205deec3a0d71f3209f77",
        },
        [15917] = {
            ["Eles colocaram essas lanternas para comemorar o encerramento do Festival da Lua."] = "7e9c620ca526252a37ea37761109af3c",
            ["Que seus anciãos $go:a; abençoem, $n, e lhe tragam sorte no ano vindouro."] = "5e8efcc987de096a86113fbf1f74025c",
            ["Vão lançar fogos a noite toda. Das 18h até o sol nascer, o céu de Eluna'ara vai ficar em chamas!"] = "3ebd4c9fbc15b539397a05f7c7e9bfb7",
            ["É a última noite do Festival da Lua. Que a sorte esteja com você!"] = "ea6aed234baf22eb98af03d184469b13",
        },
        [16012] = {
            ["Thrall mostrou grande gentileza ao me conceder abrigo em seus domínios. De qualquer forma, não quero me demorar demais. Seria uma grande desonra se eu causasse problemas ao nosso líder."] = "b9ca2ade5c180a21e305ffe165d2771c",
        },
        [16013] = {
            ["Tente não chamar muita atenção, estou esperando uma audiência com o Rei. Não que eu me importe de esperar. Me sinto bem segura com todos esses guardas parrudos por aí."] = "f555efebf575408048587026c0aa3577",
        },
        [16014] = {
            ["Saudações, $gamigo:amiga;! Que tal um capacitador ectoplásmico? Ou, quem sabe, um assimilador espectral pluridirecional?"] = "2ee56c2d70a0c3bb5d140a53ddd3fa45",
        },
        [16031] = {
            ["Eu vou ficar bem, não se preocupe comigo. Vou encontrar uma saída assim que eu terminar uns rituais de purificação aqui nesta sala. Há magia maligna aqui, $n."] = "79424cf61ac27a09aeb2a6d5ab3cbd8e",
        },
        [16032] = {
            ["Que foi agora? Não vê que estou ocupado?"] = "360a69edd614799c733b1184cf582009",
        },
        [16033] = {
            ["$n! Você veio só para me ver? Ah, mas que gentil da sua parte! Aliás, você está $glindo:linda; com essa roupa!$B$BNossa, como é bom vê-$Glo:la;. Eu fico muito sozinho aqui em cima, ainda mais que esses caipiras não conseguem me ver. Você foi muito importante para todos nós e eu nunca vou me esquecer disso!$B$BObrigado por aparecer e dar uma alô, e vê se não some de novo."] = "31cec36e221c24d2e395f87f8a13b7c7",
            ["<Bodley olha para você desconfiado, mas continua...>$B$BLá estávamos nós com o grimório em mãos quando Kormok, nosso ogro necromante de duas cabeças, nos olhou com todos os quatro olhos de um jeito muito estranho. Foi muito assustador, porque o segundo par de olhos sempre parecia meio morto – que nem uma vaca, sabe? Daí, de repente, ele arranca o amuleto que Valthalak estava usando e quebra ele.$B$BO resto do grupo enlouqueceu: uns tentando acalmar os outros que, por sua vez, queriam o amuleto para si."] = "e4059edbada4f015b06e754a44f9b6c5",
            ["Ah é, isso mesmo.$B$BEntão, a gente estava lá, invadindo o topo do Pico da Rocha Negra, lutando contra seu senhor e líder. Isso tudo foi antes de Drakkisath. Ele não era dos mais espertos, na minha opinião, mas nosso líder, Anthion Harmon – você o conheceu – adorava um desafio.$B$BPara nossa surpresa, tudo correu como planejado, até o momento em que estávamos arrancando o grimório de Valthalak dos seus dedos enrijecidos. Foi aí que o negócio desabou.$B$BQuer que eu continue? Você está com o olhar meio vidrado."] = "c5bc7008b7dc8feccc3dc8a43b1ab1a8",
            ["Caramba, não precisa insistir! Já estou quase acabando a história.$B$BEntão, o grupo inteiro estava brigando por um amuleto no meio de uma câmara gigantesca e, olha, como tinha eco naquele lugar! No fim das contas, o amuleto se quebrou em três partes, daí nós tiramos elas na sorte e cada uma delas seguiu um rumo diferente.$B$BO resto é um grande borrão na minha memória, porque logo depois o espírito de Valthalak resolveu aparecer e conjurar um monte de assassinos espectrais."] = "58af390eae1d4f73c7b54ed1448a76db",
            ["Depois disso nos separamos, foi isso que aconteceu. Eram muitas tensões, eu acho... estava virando uma bola de neve. E o episódio do amuleto acabou sendo a gota d'água.$B$BDesde então, os servos de Valthalak estão nos eliminando um por um. A maioria dos portadores do amuleto já estão mortos e tiveram suas almas corrompidas pelo que ainda havia restado do espírito de Valthalak no objeto.$B$BPor isso estou tão feliz de você estar aqui, $n. Com a sua ajuda, nós reuniremos o amuleto e o devolveremos ao lorde Valthalak!"] = "69ab7dc25b9198ce90439c7c1d193e0e",
            ["Espera aí, ô $gapressadinho:apressadinha;!$B$B<Bodley resmunga alguma coisa a respeito da impaciência dos vivos>$B$BComo eu estava dizendo, o espírito de lorde Valthalak e os assassinos espectrais que ele havia evocado com seus truques de necromancia começaram a nos atacar e, vou te contar, naquela hora, nós não estávamos em nenhuma condição de nos defendermos, daí saímos correndo. Eu me lembro que, em determinado momento, Mor Casco Gris, um dos nossos druidas, caiu e foi parar na base do pico.$B$BO resto, como dizem, é história."] = "6952da64d9a42837f0f8a0e8e30b1e67",
            ["Na verdade é bem simples, $n. Minha antiga companhia de mercenários, A Lâmina Velada, aceitou a missão errada na hora errada.$B$BFomos contratados por um goblin da Angra do Butim, um tal Gremink Pestilingue, que cobiçava o grimório do lorde Valthalak. Ou talvez houvesse alguma antiga rivalidade entre eles... Acho que agora nunca vamos saber, porque Gremink foi morto há pouco tempo por um grupo de assassinos espectrais de Valthalak. Em grande número eles são mortais.$B$BOnde é que eu estava mesmo?"] = "719549680790d3f20c149ecbf7c7c9a1",
            ["Você me vê? Você sabe o quanto eu sou ignorado aqui em cima só porque ninguém me vê? Que maravilha é falar com alguém depois de tanto tempo.$B$BEntão, você deve ter sido $genviado:enviada; por algum dos membros vivos do meu antigo grupo de mercenários, estou certo? Ora, mas é claro!$B$BMas chega de papo, pois, se você vai realmente devolver o espírito de lorde Valthalak e consertar tudo. Você tem bastante trabalho pela frente!"] = "d8a5cf6d252aa70c9685e327fb97066f",
        },
        [16070] = {
            ["Salve, $c. Não nos vimos há pouco tempo numa reunião particular? Você me parece familiar, mas a cidade é tão movimentada que nunca se sabe.$B$BSe você tiver participado da convenção, com certeza recebeu um código secreto. Fale-me o código e, em troca, eu lhe darei um prêmio especial."] = "c5afae87abc614718a9d01193dc59430",
        },
        [16076] = {
            ["Salve, $c. Não nos vimos há pouco tempo numa reunião particular? Você me parece familiar, mas a cidade é tão movimentada que nunca se sabe.$B$BSe você tiver participado da convenção, com certeza recebeu um código secreto. Fale-me o código e, em troca, eu lhe darei um prêmio especial."] = "28755471b38e6eb285e0d80db6c9498a",
        },
        [16091] = {
            ["Cumprimentos e saudações da mansão de Corvoforte, $Gaventureiro:aventureira;."] = "a71a88515d6fa1bcf5501c0265097b6d",
        },
        [16112] = {
            ["O primeiro conjunto de armadura Couraçada foi feito exclusivamente para o grão-lorde escarlate Mograine. Ao envergar a armadura completa, Mograine parecia um demônio saído das profundezas do Éter.$B$BMograine se lançava contra centenas de Flagelados, a Crematória em punho, e do outro lado saía numa confusão de fumaça e fogo enquanto seus inimigos jaziam carbonizados a seus pés... era uma visão e tanto."] = "d0454cc1a7f4f7f1c3d786915dd2f879",
            ["O que é a Irmandade da Luz? Bom... no fundo, nós somos todos membros da Aurora Argêntea, porém livres dos impedimentos da moral, da culpa e de todas essas emoções humanas inúteis. Somos como a Cruzada Escarlate, só que sem a estupidez, a falta de liderança e o fanatismo cego.$B$BNão deixe o Comandante Escarlate lhe convencer do contrário.$B$BE não deixe Tyrosus saber que eu disse isso... Eu lamentaria muito fazer ele em pedacinhos caso acontecesse alguma contenda."] = "087fc685b3d3b988443256863a127d39",
            ["Só após sua morte controversa que os cavaleiros e guerreiros de Lordaeron passaram a usar trajes parecidos em homenagem a seu herói caído. Embora a morte de Mograine tenha sido uma grande vitória para Kel'Thuzad, o martírio resultante seria sentido até o fim da guerra.$B$BOnde um caiu, muitos se ergueriam..."] = "338d2b414e7e0fbcec01d970b4aa4241",
            ["Você está falando sério? Não sabe mesmo?$B$BSe você for do tipo covarde, que tem medo de sujar as mãos, vai encontrar sucata de ferro negro com as criaturas das Estepes Ardentes e da Garganta Abrasadora.$B$BJá se você for do tipo aventureiro sanguinário, existe um monte de sucata nas masmorras do Pico da Rocha Negra e do Abismo Rocha Negra."] = "0b31ddefd183ea40f98d3eae3fd516ca",
        },
        [16113] = {
            ["Fé... alguns a perdem e outros a encontram. Não pode ser destruída, nem criada.$B$BVocê não estaria se referindo à vestimenta da Fé? Uma armadura envergada pelos nossos sacerdotes e mais devotos guerreiros na batalha contra o Flagelo durante a última guerra.$B$BPerdemos a maior parte delas... roubadas pelos demônios de Naxxramas."] = "573851fae77cd06367281ad5d921bf9b",
            ["O Lich Rei está tentando avisar o mundo de sua presença. Não podemos permitir que isso ocorra."] = "2546edb7adcfdf6f1c9a8e4e04303b07",
        },
        [16114] = {
            ["A Aurora Argêntea pode até ser um grupo de idealistas impotentes, mas o líder deles tem consciência disso. Fui enviado como emissário da Cruzada Escarlate. Um embaixador, se assim preferir... Duvido que consigamos tirar uma lasca sequer dos exércitos de Kel'Thuzad, unidos ou não, mas talvez consigamos detê-los para dar tempo suficiente para um milagre acontecer.$B$BQuanto a mim, morrerei lutando...$B$B<Marjhan balança os ombros indiferente.>"] = "7dde9ae82fc3dac0e978a835607357c8",
        },
        [16115] = {
            ["A armadura da Redenção era envergada pelos nossos mais devotados cavaleiros, uma armadura digna do Arauto da Luz!$B$BPerdemos milhares de homens na última guerra. As vestes deles foram arrancadas de suas carcaças para serem levadas a cidadela horrenda de Naxxramas.$B$BDizem que os cavaleiros da morte de Naxxramas corrompem as armaduras para servirem aos seus propósitos.$B$BÉ uma lástima..."] = "413977ef54e229a5943c4a37c970e4e7",
            ["Olhe por onde pisa, $r. Quando se trata de fazer justiça sobre os que prejudicam o mundo, nós da Irmandade da Luz não somos tão brandos quanto os nossos irmãos.$B$BAi do infeliz que irritar Korfax.$B$BAgora, se você não tem nenhum assunto a tratar comigo ou com outros integrantes da irmandade, saia para que possamos continuar a reunião."] = "ab082a0dacce89f2423a85518fe46a16",
        },
        [16116] = {
            ["<Balança a cabeça.>$B$BDepois das mortes, os Seis decidiram que a melhor coisa a se fazer era selar o cajado por trás de barreiras mágicas impenetráveis e designar um guardião para o cajado... Eu seria esse guardião."] = "c713a20e41938c73763a6be364694b66",
            ["Após a queda de Dalaran, eu deixei o Kirin Tor. Meu maior propósito era guardar Atiesh e eu o fiz durante anos, apenas para tê-lo arrancado de mim de um só golpe. Eu jurei para mim mesma que encontraria o cajado, mesmo que isso me tomasse a vida toda. Foi assim que me uni à Aurora Argêntea e é por isso que estou aqui agora."] = "e31f9aa725b12b20135051ca058312a9",
            ["Após a queda de Karazhan, o Kirin Tor enviou um grupo de magos para revirar a torre em busca de objetos de import... para fins de 'pesquisa'. Foi então que o cajado lendário foi descoberto e levado para Dalaran."] = "6122d26d8170dc3ccd4b9e61fb944a4a",
            ["Assim como Kel'Thuzad, eu fui outrora uma maga do Kirin Tor. E assim como Kel'Thuzad, eu procuro o lendário Atiesh, Grande Cajado do Guardião. Nossos destinos estão entrelaçados, $c."] = "2e1a14887634a9235eb8a2b52a40e043",
            ["Boa pergunta...$B$BSe você preferir caçar em campo aberto, tem vários elementais nas Terras Pestilentas, Azshara, Estepes Ardentes, Selva Maleva, Silithus, Hibérnia e até na Cratera Un'Goro.$B$BSe você é do tipo que ri na cara do perigo, então talvez você devesse adentrar os muros do Gládio Cruel. Ouvir dizer que várias aberrações elementais habitam aquele lugar. Você também poderia procurar os elementais empregados pelos anões Ferro Negro do Abismo Rocha Negra."] = "2ab19e8f4975368b71069106f4f9e703",
            ["Depois disso, houve uma sucessão de eventos trágicos que levou à morte todos os magos do Kirin Tor que haviam entrado em contato com Atiesh.$B$BO artefato possuía vida própria. Vida concedida a ele por Sargeras..."] = "260835e952147cbb7a876af4c9aa6cac",
            ["Depois, não há muito o que dizer. Dalaran foi quase obliterada por Arquimonde e o cajado desapareceu. Provavelmente ele foi despedaçado pelo mecanismo de emergência da barreira.$B$BHá quem acredite que o cajado foi a causa do ataque de Arquimonde."] = "24abd0790e880086be8e9845c402ee7c",
            ["Dizem que Kel'Thuzad procura o Grande Cajado do Guardião, o lendário Atiesh.$B$BIsso mesmo, o cajado que um dia fora empunhado por Medivh."] = "971c7add47ebb151a9436fa9054b5e73",
            ["Era a corrupção de um titã decaído. A corrupção de um Destruidor. Afinal, o cajado foi forjado a partir da semente do ódio. Foi isso que me trouxe até aqui..."] = "28cf85bb2ada6ed1f79286dd08cc5e99",
            ["O descendente de Aegwynn, aquele que deveria ser o último Guardião de Tirisfal – Medivh..."] = "93c3d0734d2464cd5730f70b6d5bebdd",
            ["Rastreei os muitos fragmentos do cajado mundo afora e, assim, descobri que Kel'Thuzad planejava reunificá-lo. Ele já conseguiu a posse de vários dos fragmentos, os quais foram confiados aos seus maiores tenentes.$B$BSou incapaz de exprimir a importância de manter o grande cajado do Guardião longe das garras de Kel'Thuzad. Francamente, não sei dizer quais seriam os resultados, mas sei que seria uma catástrofe de proporções épicas."] = "cbfe4959c0dccd84f4f0f7ec31d8ebe2",
            ["É uma história lendária que não tenho tempo, nem disposição para contar novamente. É importante saber que Medivh foi o último dos guardiões. O grande cajado Atiesh concentrava o poder dele, além de concentrar um poder corrompedor."] = "8a3e84c175ab25c48b49ca17b0135721",
        },
        [16123] = {
            ["Nem me fale de investimento errado!$B$BO grimório negro de lorde Valthalak valia uma fortuna no mercado negro. É uma pena que ele não tenha aceitado o roubo numa boa. Aquele fedorento acabou conosco mesmo já estando morto há meses!"] = "7851f71608300be24d2a60246c177a38",
        },
        [16131] = {
            ["Boa pergunta, $r. Na minha juventude, eu era livre, leve e solto para fazer o que quisesse no mundo. Naquela época, eu cantava num quarteto vocal chamado Quatro Dons. Foi aí que eu aprendi a confeccionar a Ceifa-ossos."] = "c5eeeaf1edcbad1bef6a552484b6b991",
            ["Como diz o título, sou um assassino da Cruzada Escarlate. De dia, extermino alvos de alta prioridade; de noite, vou para a discoteca de Geringontzan. A minha paixão verdadeira é a dança. Matar é só para pagar as contas."] = "512f340d076023b4c9448a6a0aa5f962",
            ["Isso aí, Ceifa-ossos. Foi o nosso tenor, um cara normal, chamado Dom Júlio, saca? Foi ele que me colocou nesse esquema. Ele viajava por Lordaeron e adquiria muitas habilidades interessantes: uma delas era pegar os ossos de um Flagelado e transformar eles num conjunto letal de armadura de couro, perfeita para assassinos."] = "d6ee820d31d12325db3bb0117d5ad5ed",
            ["O título é um pouco assustador, mas quando você me conhecer de verdade, vai ver que sou um cara legal."] = "7d3224526057b707f3979b7b1671e479",
            ["Somente sócios, $gespertinho:espertinha;!"] = "e9681ae779f33089e0a1a4491af83568",
            ["Sou tão normal quanto qualquer um, gente boa. Acredite se quiser, mas eu SEI confeccionar a armadura. Se tiver interesse, podemos fazer negócios. Quanto antes eu sair do ramo do assassinato, melhor."] = "f58bd8742f434e11faf30ac0397cb63c",
            ["Você é $gcego:cega; por acaso? Não viu o MAR DE CRIATURAS ESQUELÉTICAS que tem por aqui?$B$B<Rohan suspira.>$B$BSe você preferir ficar ao ar livre, tem vários esqueletos tanto nas Terras Pestilentas Orientais, quanto nas Ocidentais. Vai por mim, é impossível não notá-los e, de qualquer forma, eles com certeza vão notar você.$B$BAgora, se preferir as masmorras, Stratholme e Scolomântia são os melhores lugares para achar fragmentos de osso."] = "13a767725c325fa51d467e80639b5c7b",
        },
        [16132] = {
            ["A habilidade sobrenatural dos carnífices da cripta de caçar e aniquilar suas presas é estudada e exaltada pelos homens da minha profissão. Eu mesmo já matei milhares dessas feras em minha cruzada para livrar o mundo do Flagelo.$B$BEmbora eu abomine a natureza impiedosa do carnífice da cripta, suas habilidades são admiráveis. Ele tem uma função e a executa com primor."] = "1bb2d36c1471ccc6854f72988e3b2362",
            ["Descobri um uso para a carapaça do carnífice da cripta e suas várias partes do corpo. Posso manufaturar um conjunto de armadura extremamente leve e bastante letal juntando os fragmentos com algumas das armaduras mágicas profanadas perdidas em Naxxramas."] = "c3277c86a4fa82a1bddd12127f42cee9",
            ["Esses imundos estão por toda parte.$B$BCaso você prefira caçar ao ar livre, eles ficam aos montes no Bosque Pestilento e na Várzea do Medo, e tem um bom número deles no Túnel Terrorteia. Eles também aparecem em quase todos os acampamentos do Flagelo nas Terras Pestilentas.$B$BSe você for daqueles desbravadores de masmorras, tem um monte deles em Stratholme e também tem um pouco de necroteias em Scolomântia."] = "86a91c29a823bc19ba74c174cebf69ae",
            ["Quase que eles enviaram meu irmão Lobato para esta reunião. Ele mal consegue tomar conta daquelas hienas dele, que dirá representar decentemente a Cruzada Escarlate."] = "55bee4d94fe2ec071c1f49801c48e21a",
        },
        [16133] = {
            ["Não falto com minha palavra, verme. A escuridão contida em tais itens poderia muito bem destruir a nós dois. Por isso o preço é tão alto. Se hei de morrer, que seja como um homem rico.$B$BQuanto a você, importo-me tanto com a sua morte quanto me importaria com a de um gnoll. Quero apenas que faça como ordenei. Traga-me o que eu ordenar e ambos nos beneficiaremos... ou morreremos, como já disse..."] = "c3138924933336621f5295591b7152ae",
            ["Que você quer, seu pau-mandado? Se você não sumir da minha vista agora, vou lhe mostrar porque é que me chamam de Arauto da Ira."] = "46c26045969305b4f1afa87dc761ac0c",
            ["É poder, imbecil.$B$B<Os olhos de Mataus escurecem.>$B$BEsses tolos mandam idiotas como você para Naxxramas a fim de recuperar uma armadura profanada para purificá-la e restituir os pedaços à antiga glória.$B$B<Mataus cospe.>$B$BSó de pensar em tamanha estupidez me dá ânsia de vômito.$B$BEu também procuro essa armadura, mas em sua forma mais corrompida e profanada."] = "c943281a6d8472a873a6c97a00f1de85",
        },
        [16134] = {
            ["Estava esper...$B$B<Rimblat tosse.>$B$BDesculpe-me. É um velho hábito. Eu sou Rimblat, da Harmonia Telúrica."] = "2c121d996480b972ca128fe4dd17568b",
            ["Eu era um tauren jovem naquela época, mal havia chegado à adolescência, mas eu já sabia que os corajosos heróis que lutavam pela nossa liberdade estariam bem protegidos sob as vestes do meu clã."] = "102e0b4ad57167106f63887340efcdd5",
            ["Na última guerra, os taurens lutaram. Os xamãs foram enviados para defender o mundo da invasão do Flagelo. A maioria deles perdeu a vida. Muitos foram dilacerados e tiveram seus membros usados em experimentos horrendos naquela cidadela maldita. Lamento a morte deles, mas sua coragem enche meu coração de orgulho."] = "65e7b100fb21e8d6d72f6a72a8e28b8f",
            ["O nome Quebraterra pertence à minha família há centenas de anos. Eu, assim como meu pai e meu avô antes dele, herdei o direito de confeccionar a vestimenta Quebraterra."] = "261c833a674804c528c3991040fe6265",
        },
        [16135] = {
            ["Acho que sim. Rimblat já conseguiu provar que é possível nascer vida da terra seca. Agora, precisamos encontrar um meio de reproduzi-la e, principalmente, de sustentá-la.$B$BEnquanto eu estiver aqui, meus serviços também estarão a disposição dos aventureiros que adentram Naxxramas."] = "2c8bea531a145f78fd5e857b6b8fabd4",
            ["Olá, $c. Peço que me dê licença, pois estou conversando com Rimblat. Ele acredita que esta terra ainda não está condenada."] = "f7cb5d818b4259306750c7395a10a00f",
            ["Se você for o tipo de pessoa que prefere caçar em campo aberto, tanto os arvorosos da Selva Maleva, quanto as açoitadeiras de Un'Goro são uma ótima fonte.$B$BSe você for do tipo que gosta de correr riscos, as alas leste e oeste do Gládio Cruel possuem um estoque praticamente infinito de frondes selvagens."] = "ca612f9695245d53b26272938714b047",
            ["Sou um artesão de renome, $c. Com a matéria prima adequada, posso confeccionar uma armadura chamada Andassonho. Druidas e xamãs são atraídos pelos poderes mágicos dessa armadura. Está $ginteressado:interessada;?"] = "182a2f807168b02644f4daff8caa6b4b",
            ["Viemos todos por razões diferentes, $c.$B$B<Rayne sorri.>$B$BVim me encontrar com Rimblat, da Harmonia Telúrica. Ele tem teorias interessantes acerca da purificação destas terras."] = "32fb9a5f34cae334b11ddc1ef3aaafda",
        },
        [16212] = {
            ["Esse seu perfume ofende as minhas narinas, $r. Diga logo o que quer e suma da minha vista!"] = "b5c51729cbfc4944277ef2a9a1158a7e",
        },
        [16226] = {
            ["Não tenha medo da espada, $gbobo:boba;. É o pernil que é o terror!"] = "aa468b41ee1967bb79c4f9ff0c0d575f",
        },
        [16230] = {
            ["O sectário está num transe profundo..."] = "73f0462573697c404b28308bec6f882a",
        },
        [16254] = {
            ["<O marechal-de-campo Câmara vocifera.>$B$BEntão você estava entre a gentinha que ajudou Didier a trazer os suprimentos para cá? E onde está o resto? Sei que você não fez isso $gsozinho:sozinha;. Vira-latas como você geralmente andam em bando.$B$BTanto faz, dê-me a maldita escritura para eu assiná-la logo de uma vez."] = "51a682137b7a6db94a26971a20130651",
        },
        [16256] = {
            ["A Bastilha da Presa Negra fica a sul de Pinhaprata, logo a norte do Vilarejo Lenhardente."] = "17d13be0366794572061fb3fbb409ee6",
            ["A Escola de Necromancia conhecida como Scolomântia fica na ilha arruinada de Castro das Flechas, nas Terras Pestilentas Ocidentais."] = "4414ebedf67147d4801e58071b11c237",
            ["A Montanha Rocha Negra fica a sul da Garganta Abrasadora e a norte das Estepes Ardentes."] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["A cidade arruinada de Stratholme fica nas Terras Pestilentas Orientais, a norte do Bosque Pestilento."] = "d9516bdeb534c80940a3be1f4600bf04",
            ["A cidade devastada pelo sol é lar dos trolls Zangareia, conhecidos por sua malevolência e rituais sombrios. Lendas trólicas falam de uma espada chamada Sul'thraze, a Açoitadora, uma arma capaz de instigar o medo e a fraqueza mesmo no mais formidável dos inimigos. Há muito tempo, a arma fora partida ao meio. Segundo rumores, as duas metades se encontram entre os muros de Zul'Farrak."] = "0f7f53045dc845e1ab759203cc598d30",
            ["A entrada da Caverna Ululante fica no Oásis das Águas Claras, a sudoeste da Encruzilhada, nos Sertões."] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["A poderosa fortaleza, escavada no âmago da Montanha Rocha Negra, pertencera aos sinistros anões Rocha Negra durante séculos, até que Nefarian, o ardiloso filho de Asa da Morte, tomou posse do pico superior e engendrou uma guerra contra os anões que detinham as profundezas vulcânicas da montanha. Ao descobrir que os anões eram liderados pelo poderoso elemental do fogo Ragnaros, Nefarian jurou que esmagaria seus inimigos e clamaria a Montanha Rocha Negra para si."] = "3644fa36f35ecdc5947046c71b54837a",
            ["Ao dar provas de amor para os cidadãos, eles lhe darão, em troca, presentes diversos. Alguns você pode querer manter para si e usar, enquanto outros você pode juntar para dar ao seu herói favorito! Para entregá-los, fale com Ligeirinho Coração.$B$BO Ligeirinho fica perto de Bolvar, Magni ou Tyrande."] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["Ao dar provas de amor para os cidadãos, eles lhe darão, em troca, presentes diversos. Alguns você pode querer manter para si e usar, enquanto outros você pode juntar para dar ao seu herói favorito! Para entregá-los, fale com Ligeirinho Coração.$B$BO Ligeirinho fica perto de Caerne, de Sylvana e de Thrall."] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["Ao usar perfume ou colônia, você verá quem está amoroso. São essas pessoas que aceitarão as provas de amor e darão um presente em troca.$B$BMas lembre-se: para dar uma prova de amor a alguém, você precisa da fragrância correta! Homens gostam do aroma do perfume, e mulheres preferem o da colônia."] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["As Cavernas Ígneas consistem numa rede de cavernas vulcânicas sob a nova capital órquica de Orgrimmar. Há boatos recentes de que uma seita leal ao Concílio das Sombras reside nas profundezas das Cavernas Ígneas. A seita, conhecida como a Lâmina Ardente, é uma ameaça à soberania de Durotar. Muitos acreditam que o chefe guerreiro Thrall está ciente da existência da Lâmina e que decidiu não destruí-la na esperança de que os membros dela o levem ao Concílio das Sombras."] = "4a0636d96305a16097c01ed6971f7971",
            ["As Cavernas Ígneas encontram-se abaixo do Antro das Sombras, no centro de Orgrimmar."] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["As Minas Mortas ficam abaixo de Arroio da Lua, a sul de Cerro Oeste."] = "cce75935af7718f82fcb4c3d13f23020",
            ["As Minas Mortas já foram o maior centro produtor de ouro em terras humanas e, agora, são o lar da Irmandade Défias, que transformaram os túneis escuros em seu santuário particular. Correm rumores de que os ladrões recrutaram goblins para ajudá-los a construir algo terrível no fundo das minas, mas não se sabe ainda do que se trata. De acordo com os rumores, a entrada das Minas Mortas fica na pacata vila de Arroio da Lua."] = "e118425d7cca455fae7064446900535b",
            ["As Profundezas Negras ficam no extremo norte da Praia de Zoram, ao longo da costa do Vale Gris."] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["As ruínas de Zul'Farrak ficam no canto noroeste do Deserto de Tanaris."] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["As ruínas do Gládio Cruel ficam na região central de Feralas."] = "863a0466292f35423e25fb6b1e18e872",
            ["Construída há doze mil anos por uma seita secreta de feiticeiros noctiélficos, a antiga cidade de Eldre'Thalas era usada para proteger os mais preciosos segredos arcanos da Rainha Azshara. Embora tenha sido devastada pela Grande Cisão do mundo, grande parte da magnífica cidade permaneceu erguida no que hoje é o imponente Gládio Cruel. Os três ilustres distritos foram assolados por toda sorte de criatura, especialmente por Altaneiros espectrais, sátiros hediondos e ogros bestiais."] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["Durante a Guerra dos Antigos, o semideus Agamaggan se ergueu contra a Legião Ardente. O gigantesco javali foi derrotado e, nos locais onde seu sangue foi derramado, brotaram, com o passar do tempo, imensas trepadeiras espinhosas. Os javatuscos ocuparam os espinhais e os consideram sagrados. O coração dessas colônias cobertas de espinhos é o Urzal. O Urzal dos Tuscos foi conquistado pela bruxa má Charlga Talhaflanco. Especula-se que ela esteja negociando com agentes do Flagelo... com propósitos insidiosos..."] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["Feito do mesmo espinhal do Urzal dos Tuscos, o Urzal dos Mortos é tradicionalmente a capital dos javatuscos. O labirinto de espinhais abriga um exército notável de leais javatuscos, assim como seus sumo sacerdotes – a tribo Cabeça da Morte. Recentemente, contudo, o rústico covil foi engolido pelas sombras. Agentes mortos-vivos do Flagelo, liderados pelo lich Amnennar, o Frigífero, dominaram os javatuscos e transformaram o labirinto de espinhos num bastião do poder morto-vivo."] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["Frustrado com a falta de progresso dos teurgos de Dalaran contra os mortos-vivos na Terceira Guerra, o arquimago Arugal preferiu evocar os worgens de outra dimensão para engrossar suas fileiras cada vez menores. Os homens-lobo massacraram o Flagelo, depois se viraram contra os próprios teurgos e sitiaram a bastilha do nobre barão Silverlaine. Rapidamente, o forte decaiu em ruínas e sombras. Enlouquecido pela culpa, Arugal adotou os worgens como filhos e se recolheu à bastilha, então renomeada como Bastilha da Presa Negra."] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["Gnomeregan fica na parte oeste de Dun Morogh."] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["Há mais de mil anos, um grupo de sacerdotes trólicos conhecidos como os Atal'ai tentaram trazer de volta a Azeroth o deus do sangue Hakkar, o Esfolador de Almas. Após a guerra civil que se sucedeu, os sacerdotes foram derrotados e exilados no Pântano das Mágoas. Lá eles ergueram um templo para se preparar para a chegada de Hakkar ao mundo físico. Ysera, um dos Aspectos Dragônicos, descobriu os planos dos Atal'ai e afundou o templo sob as águas do pântano. Até hoje, as ruínas do templo são guardadas pelos poderosos dragões verdes."] = "7dc247370c0f46388922e4ad2824f973",
            ["Há pouco tempo, um druida noctiélfico chamado Naralex descobriu uma rede de cavernas subterrâneas no coração dos Sertões. Ele achou que poderia usar as nascentes das cavernas para tornar os Sertões viçosos de novo e passou a canalizar as energias do lendário Sonho Esmeralda. A visão dele, de alguma forma, se transformou em pesadelo, e, em pouco tempo, a Caverna Ululante se transformou em um covil de predadores mortais. Dizem que Naralex ainda reside em algum lugar do labirinto, aprisionado nos confins do Sonho Esmeralda.  "] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["Localizada em Dun Morogh, Gnomeregan foi a capital dos gnomos por muitas gerações, mas recentemente ela foi infestada por troggs mutantes. Numa desesperada tentativa de retaliação, o Grão-faz-tudo Mekkatorque ordenou, como medida de emergência, a abertura dos depósitos de lixo radioativo da cidade. Mesmo sob efeito da radiação, o cerco dos troggs prosseguiu implacável e os gnomos foram forçados a se refugiar na cidade enânica de Altaforja, onde, atualmente, o Grão-faz-tudo convoca almas corajosas para ajudar na retomada da querida cidade gnômica."] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["Maraudon fica no centro da costa oeste de Desolação, no Vale das Lanças."] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["Maraudon é um dos locais mais sagrados de toda Desolação. O grande templo-caverna é o sepulcro de Zaetar, um dos dois filhos imortais do semideus Cenarius. Reza a lenda que Zaetar e a princesa elemental da terra Theradras deram origem à raça bastarda dos centauros. Diz-se que, no momento em que se ergueram, os bárbaros centauros se voltaram contra o próprio pai e o mataram. Há quem creia que Theradras, em seu sofrimento, aprisionou o espírito de Zaetar na sinuosa caverna, usando a energia dele para fins malignos."] = "44f65d16974643e3b29f727a67787ad0",
            ["Não, eu não, mas tem muita gente procurando amor por aí. Você devia comprar as minhas provas de amor, passar uma colônia ou um perfume e, depois, disseminar o amor!"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["O Cárcere de Ventobravo fica perto do Distrito dos Magos de Ventobravo."] = "8b063ee787233090be02c8d7fc8e58a7",
            ["O Cárcere é um complexo de prisões de segurança máxima escondido abaixo do Distrito do Canal de Ventobravo. Presidida pelo carcereiro-chefe Thelágua, os Cárceres são lar de golpistas, insurgentes políticos, assassinos e uma malta dos mais perigosos criminosos da região. Há pouco, uma revolta dos prisioneiros resultou num estado de pandemônio dentro dos Cárceres, no qual os guardas foram expulsos e os presos vagam livres."] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["O Monastério Escarlate fica nas montanhas a nordeste das Clareiras de Tirisfal."] = "fe604977d24d31743e5481d5dcda2e88",
            ["O Templo Submerso fica no centro de um lago enorme, que fica a leste do Pântano das Mágoas."] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["O Urzal dos Mortos fica na extremidade sul dos Sertões, do lado leste da estrada."] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["O Urzal dos Tuscos fica na extremidade sul dos Sertões, do lado oeste da estrada."] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["O monastério fora, outrora, um centro de aprendizado e conhecimento. Com o erguimento do Flagelo durante a Terceira Guerra, o pacífico monastério foi convertido num bastião da fanática Cruzada Escarlate. Os Cruzados são intolerantes com todas as raças não-humanas, independente de afiliação. Eles acreditam que todas elas são potenciais portadoras da peste da morte-viva e que, por isso, devem ser destruídas."] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["Outrora capital dos anões Ferro Negro, o labirinto vulcânico serve, agora, de trono para Ragnaros, o Senhor do Fogo. Ragnaros descobriu como criar vida a partir da rocha e planeja construir um exército de golens invencíveis para ajudá-lo na conquista da Montanha Rocha Negra. Obcecado por derrotar Nefarian e seus lacaios dragônicos, Ragnaros recorrerá a qualquer meio para alcançar a vitória."] = "e4835262a6e71a36692d90aedbb66c42",
            ["Outrora o tesouro a norte de Lordaeron, foi na cidade de Stratholme que o Príncipe Arthas se virou contra o seu mentor, Uther, o Arauto da Luz, e matou centenas de seguidores da coroa, os quais ele acreditava haver contraído a peste da morte-viva. Pouco depois, Arthas se entregou ao Lich Rei. A cidade arruinada é atualmente habitada pelos mortos-vivos do Flagelo, liderados por Kel'Thuzad, e por um contingente de Cruzados Escarlates, liderados pelo grão-cruzado Dathrohan. A luta entre os dois lados é constante e violenta."] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["Provas de amor são recadinhos afetuosos que você manda para os amorosos habitantes de cidades e aldeias. As pessoas vão retribuir com um presente de afeto.$B$BOu, se você já for $go adorado:a adorada; de alguém, as pessoas lhe darão, pelo menos, um presente de amizade."] = "cd40129110d4c4917a537fef57180329",
            ["Scolomântia abriga-se nas criptas abaixo de Castro das Flechas. Outrora pertencente à nobre família Barov, a bastilha encontrou sua ruína na Segunda Guerra. Ao arrebanhar seguidores para a Seita dos Malditos, Kel'Thuzad prometia imortalidade a todos que servissem o Lich Rei. Os Barov caíram sob seu domínio e doaram a bastilha, mas os sectários mataram a família e transformaram as criptas em uma escola de necromancia. Embora Kel'Thuzad não mais resida na escola, os sectários e instrutores continuam lá."] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["Seja bem-$gvindo:vinda; à Capela Esperança da Luz, $gforasteiro:forasteira;."] = "62d77d311ff95b739586b58c132d853b",
            ["Situado no Vale Gris, ao longo da Praia de Zoram, as Profundezas Negras foram, outrora, um glorioso templo dedicado à deusa da lua, Eluna. Contudo, a grande Cisão destruiu o templo, afundando-o sob as ondas do Mar Velado. Ele permaneceu intocado, até que, atraídos pelo poder ancestral, as nagas e os sátiros emergiram para investigar os seus segredos. Dizem as lendas que a fera ancestral Aku'mai fez das ruínas do templo o seu covil."] = "639f5e4137099522e1302487ff27f679",
            ["Uldaman fica na extremidade norte dos Ermos."] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["Uldaman é um antigo refúgio titânico oculto sob a terra desde a criação do mundo. Escavações recentes empreendidas pelos anões em Uldaman libertaram a primeira, e fracassada, criação dos titãs: os troggs. Dizem as lendas que, ao perceberem que os troggs foram um fracasso, os titãs tentaram mais uma vez, resultando na criação da raça enânica. Esses segredos estão gravados nos lendários Discos de Norgannon, artefatos gigantescos que jazem sob a antiga cidade, protegidos por constructos gigantescos feitos de pedra viva.  "] = "a25c5d7842af31618a063b3d3ce15fed",
            ["Você tem interesse em explorar alguma dessas masmorras?"] = "9211a5a83384bc6bf667f9e87661f2b5",
        },
        [16283] = {
            ["Normalmente saem umas duas caravanas por dia – e que as minhas barbas peguem fogo se o Flagelo não emboscou as mulas de Didier para impedir o carregamento de chegar nas linhas de frente! Isso é a coisa mais louca que eu já vi... se pelo menos a gente contasse com uns aventureiros para proteger os carregamentos..."] = "b4e6217834a34f95034b22e071d3a451",
        },
        [16284] = {
            ["Tenho coisas demais para fazer e tempo de menos para fazê-las, $r! Por favor, não me atrapalhe."] = "f21ac82310364bee548aaa65db9ae740",
            ["Tenho coisas demais para fazer e tempo de menos para fazê-las, $r! Por favor, não me atrapalhe.$B$BSe você estiver $Ginfectado:infectada; com visgo de verme ou putrefação do carniçal, eu posso ajudá-$Glo:la;."] = "69087ca98832c4d531ebd24380d184e3",
        },
        [16376] = {
            ["Uma noite, o mestre artesão Omarion sumiu... que nem um pum soltado na ventania – puf! Foi-se! Humpf, agora eu tenho que fabricar tudo para os garotos nas linhas de frente sozinho."] = "9cb182e6099250bd1e21445a5a8a786a",
        },
        [16381] = {
            ["<Tarsis está gravemente ferido.>"] = "f9da3b9d9bfb527b32aa364ef806b9b5",
        },
        [16384] = {
            ["A batalha foi vencida. Por enquanto, o Flagelo não nos perturbará. Os nossos recursos podem ser canalizados para ajudá-$Glo:la;, em agradecimento e preparação para o futuro."] = "ebde1b78097e360ae80271b45ac8ec9b",
            ["A batalha vai bem. As forças do Flagelo parecem enfraquecidas. Creio ser apenas questão de tempo até nós os expulsarmos da costa. Concentrarei minhas magias em você para ajudá-$Glo:la; na luta."] = "4d4e9052d3c36392e6211cb442ea3b1e",
            ["Os primeiros passos da luta contra o Flagelo correram bem. Já obtivemos algumas vitórias e eu espero que, com a minha ajuda, você vença as batalhas futuras."] = "0973188afdf5745ee7a53c42da926c63",
        },
        [16395] = {
            ["A batalha foi vencida. Por enquanto, o Flagelo não nos perturbará. Os nossos recursos podem ser canalizados para ajudá-$Glo:la;, em agradecimento e preparação para o futuro."] = "4b36cae8ffab10bd243caafa37fd7ebd",
