        [142715] = {
            ["Eraka no Kimbul$BDeus dos Tigres, Senhor das Feras, Rei dos Felinos, a Perdição da Caça$B$BUeetay no Mueh'zala$BDeus da Morte, Pai do Sono, Filho do Tempo, o Amigo da Noite."] = "23565b681fd0e1e4b4d5ee631293f067",
