        [144063] = {
            ["O santuário foi construído há muitos anos pelos elfos noturnos que um dia habitaram esta terra.$B$BQue segredos poderia esconder?"] = "bdffb7bd4c1a549ca21fce4994c04b2e",
        },
        [148498] = {
            ["O altar parece chamar você como se estivesse vivo."] = "547f7a85e9b61fb09fdce63531b6446c",
        },
        [148836] = {
            ["O antigo Altar de Hakkar se ergue silencioso perto da entrada do aposento.$B$BAo olhar para as sacadas acima dele, você nota uma estátua de serpente em cada uma. As estátuas parecem bastante com as que estão no altar à sua frente. Elas devem ter alguma relação..."] = "91b59c0582fdc11756948115c740b617",
        },
        [160445] = {
            ["Os restos estão cobertos de moscas e vermes."] = "2f784284d20f290e01140cc7e43f3bbc",
        },
        [164955] = {
            ["As Torres de Cristal de Un'Goro são um mistério completo. Para os poucos habitantes daqui, elas são uma fonte de lenda, com muita especulação quanto ao propósito delas."] = "9658dbe477ee985df565821f1fefa775",
            ["Os segredos escondidos dentro das Torres da Cratera de Un'Goro agora são seus. Visite as Torres a qualquer hora para acessar o poder delas e obter recursos úteis."] = "d639df313298d68d7a237f950f24a630",
            ["Uma inspeção mais rigorosa da torre leva você a encontrar uma pequena mesa que contém cristais amarelos, vermelhos e verdes organizados no que parece ser uma formação específica.$B$BUm grande círculo amarelo de cristais está flanqueado de cada lado por um círculo menor de cristais vermelhos e outro de cristais verdes.$B$BVocê anota cuidadosamente as cores dos cristais, sabendo que J.D. pode ter muito interesse no que você encontrou."] = "a9edab8eb63991a1d8f002b277b1332a",
        },
        [164956] = {
            ["As Torres de Cristal de Un'Goro são um mistério completo. Para os poucos habitantes daqui, elas são uma fonte de lenda, com muita especulação quanto ao propósito delas."] = "9658dbe477ee985df565821f1fefa775",
            ["Os segredos escondidos dentro das Torres da Cratera de Un'Goro agora são seus. Visite as Torres a qualquer hora para acessar o poder delas e obter recursos úteis."] = "d639df313298d68d7a237f950f24a630",
            ["Uma inspeção mais rigorosa da torre leva você a encontrar uma pequena mesa que contém cristais vermelhos, azuis e verdes organizados no que parece ser uma formação específica.$B$BUm grande círculo vermelho de cristais está flanqueado de cada lado por um círculo menor de cristais azuis e outro de cristais verdes.$B$BVocê anota cuidadosamente as cores dos cristais, sabendo que J.D. pode ter muito interesse no que você encontrou."] = "5c6602e9f23f886ebab0f831c71cbfba",
