        [180456] = {
            ["Desapareça, infiel! Que você seja $gengolido:engolida; pelo Abismo!"] = "01594454427de3b4452e20be980b7818",
            ["Ouve-se um sussurro vindo do interior da pedra:$B$B'Saudações, $Gpequenino:pequenina;. Traz alguma notícia para o Templário?'"] = "66471c117f9a9c8fb2c8bcbff27683fb",
        },
        [180461] = {
            ["Como ousa conversar com um duque do Concílio, verme?"] = "d39f90b279f06892c664f53d9d8191a0",
            ["Ouve-se uma voz muito clara vindo do interior da pedra:$B$B'Em respeito ao seu título, vamos ouvi-$glo:la;, mas não abuse de nossa paciência, $c. O concílio não tem tempo para boatarias de um tipo como o seu.'"] = "37d313298adafe97bca139d3d41d6c87",
            ["Ouve-se uma voz muito clara vindo do interior da pedra:$B$B'Onde está seu Medalhão de Transporte, $gpequenino:pequenina;? Sem a prova de que possui um título, não é permitido falar aos duques...'"] = "ed63d78e311e71ef7884338ead2cb4d4",
        },
        [180466] = {
            ["De sob a pedra se ergue uma voz de trovão:$B$B'Que é isto?! Sinto a presença de $gum:uma; reles $gsectário:sectário;! Desapareça, verme, ou enfrente a ira dos senhores do Concílio!'"] = "5fb610919b3f9ee9e77b9a37bbabaaea",
            ["De sob a pedra se ergue uma voz de trovão:$B$B'Sinto o seu Medalhão de Transporte, $gsectário:sectária;, mas onde está o seu Anel de Suserania? Você é $Gum dos:uma das; comandantes do Martelo do Crepúsculo, ou vem sob o mando dos seus superiores?'"] = "e9af3f58bfcd009f6ff72f930ea3882f",
            ["Que inseto é este diante dos senhores do Concílio? Sem dúvida, um inseto que deseja ser esmagado!"] = "9f2e8057a4162af2cc00fd83ab0ece74",
            ["Uma voz de trovão surge de debaixo da pedra:$B$B'Saudações, comandante. Que notícias de Silithus você traz aos Senhores do Concílio?'"] = "9e096eb8c378bcc66b01591b1b44e830",
        },
        [180518] = {
            ["Desapareça, infiel! Que você seja $gengolido:engolida; pelo Abismo!"] = "01594454427de3b4452e20be980b7818",
            ["Ouve-se um sussurro vindo do interior da pedra:$B$B'Saudações, $Gpequenino:pequenina;. Traz alguma notícia para o Templário?'"] = "66471c117f9a9c8fb2c8bcbff27683fb",
        },
        [180529] = {
